                else:
                    run_response.tools.extend(tool_executions_list)

                # Format tool calls whenever new ones are added during streaming
                run_response.formatted_tool_calls = format_tool_calls(run_response.tools)
        # If the model response is a tool_call_started, add the tool call to the run_response
        elif (
            model_response_event.event == ModelResponseEvent.tool_call_started.value
        ):  # Add tool calls to the run_response
            tool_executions_list = model_response_event.tool_executions
            if tool_executions_list is not None:
                # Add tool calls to the agent.run_response
                if run_response.tools is None:
                    run_response.tools = tool_executions_list
                else:
                    run_response.tools.extend(tool_executions_list)

                # Format tool calls whenever new ones are added during streaming
                run_response.formatted_tool_calls = format_tool_calls(run_response.tools)

                # Yield each tool call started event
                for tool in tool_executions_list:
                    yield self._handle_event(
                        create_tool_call_started_event(from_run_response=run_response, tool=tool), run_response
                    )

        # If the model response is a tool_call_completed, update the existing tool call in the run_response
        elif model_response_event.event == ModelResponseEvent.tool_call_completed.value:
            reasoning_step: Optional[ReasoningStep] = None

            tool_executions_list = model_response_event.tool_executions
            if tool_executions_list is not None:
                # Update the existing tool call in the run_response
                if run_response.tools:
                    # Create a mapping of tool_call_id to index
                    tool_call_index_map = {
                        tc.tool_call_id: i for i, tc in enumerate(run_response.tools) if tc.tool_call_id is not None
                    }
                    # Process tool calls
                    for tool_call_dict in tool_executions_list:
                        tool_call_id = tool_call_dict.tool_call_id or ""
                        index = tool_call_index_map.get(tool_call_id)
                        if index is not None:
                            run_response.tools[index] = tool_call_dict
                else:
                    run_response.tools = tool_executions_list

                # Only iterate through new tool calls
                for tool_call in tool_executions_list:
                    tool_name = tool_call.tool_name or ""
                    if tool_name.lower() in ["think", "analyze"]:
                        tool_args = tool_call.tool_args or {}

                        reasoning_step = self.update_reasoning_content_from_tool_call(tool_name, tool_args)

                        metrics = tool_call.metrics
                        if metrics is not None and metrics.time is not None:
                            reasoning_state["reasoning_time_taken"] = reasoning_state[
                                "reasoning_time_taken"
                            ] + float(metrics.time)
                    yield self._handle_event(
                        create_tool_call_completed_event(
                            from_run_response=run_response, tool=tool_call, content=model_response_event.content
                        ),
                        run_response,
                    )

            if stream_intermediate_steps:
                if reasoning_step is not None:
                    if not reasoning_state["reasoning_started"]:
                        yield self._handle_event(
                            create_reasoning_started_event(from_run_response=run_response), run_response
                        )
                        reasoning_state["reasoning_started"] = True

                    yield self._handle_event(
                        create_reasoning_step_event(
                            from_run_response=run_response,
                            reasoning_step=reasoning_step,
                            reasoning_content=run_response.reasoning_content or "",
                        ),
                        run_response,
                    )

def _convert_response_to_structured_format(self, run_response: Union[RunResponse, ModelResponse]):
    # Convert the response to the structured format if needed
    if self.response_model is not None and not isinstance(run_response.content, self.response_model):
        if isinstance(run_response.content, str) and self.parse_response:
            try:
                structured_output = parse_response_model_str(run_response.content, self.response_model)

                # Update RunResponse
                if structured_output is not None:
                    run_response.content = structured_output
                    if hasattr(run_response, "content_type"):
                        run_response.content_type = self.response_model.__name__
                else:
                    log_warning("Failed to convert response to response_model")
            except Exception as e:
                log_warning(f"Failed to convert response to output model: {e}")
        else:
            log_warning("Something went wrong. Run response content is not a string")

def _handle_model_response_chunk(
    self,
    run_response: RunResponse,
    model_response: ModelResponse,
    model_response_event: Union[ModelResponse, RunResponseEvent, TeamRunResponseEvent],
    reasoning_state: Dict[str, Any],
    stream_intermediate_steps: bool = False,
) -> Iterator[RunResponseEvent]:
    if isinstance(model_response_event, tuple(get_args(RunResponseEvent))) or isinstance(
        model_response_event, tuple(get_args(TeamRunResponseEvent))
    ):
        # We just bubble the event up
        yield self._handle_event(model_response_event, run_response)  # type: ignore
    else:
        model_response_event = cast(ModelResponse, model_response_event)
        # If the model response is an assistant_response, yield a RunResponse
        if model_response_event.event == ModelResponseEvent.assistant_response.value:
            content_type = "str"

            # Process content and thinking
            if model_response_event.content is not None:
                if self.should_parse_structured_output:
                    model_response.content = model_response_event.content
                    content_type = self.response_model.__name__
                    run_response.content = model_response.content
                    run_response.content_type = content_type
                    self._convert_response_to_structured_format(model_response)
                else:
                    model_response.content = (model_response.content or "") + model_response_event.content
                    run_response.content = model_response.content
                    run_response.content_type = "str"

            if model_response_event.thinking is not None:
                model_response.thinking = (model_response.thinking or "") + model_response_event.thinking
                run_response.thinking = model_response.thinking

            if model_response_event.redacted_thinking is not None:
                model_response.redacted_thinking = (
                    model_response.redacted_thinking or ""
                ) + model_response_event.redacted_thinking

                # We only have thinking on response
                run_response.thinking = model_response.redacted_thinking

            if model_response_event.citations is not None:
                # We get citations in one chunk
                run_response.citations = model_response_event.citations

            # Only yield if we have content to show
            if content_type != "str":
                yield self._handle_event(
                    create_run_response_content_event(
                        from_run_response=run_response,
                        content=model_response.content,
                        content_type=content_type,
                    ),
                    run_response,
                )
            elif (
                model_response_event.content is not None
                or model_response_event.thinking is not None
                or model_response_event.redacted_thinking is not None
                or model_response_event.citations is not None
            ):
                yield self._handle_event(
                    create_run_response_content_event(
                        from_run_response=run_response,
                        content=model_response_event.content,
                        thinking=model_response_event.thinking,
                        redacted_thinking=model_response_event.redacted_thinking,
                        citations=model_response_event.citations,
                    ),
                    run_response,
                )

            # Process audio
            if model_response_event.audio is not None:
                if model_response.audio is None:
                    model_response.audio = AudioResponse(id=str(uuid4()), content="", transcript="")

                if model_response_event.audio.id is not None:
                    model_response.audio.id = model_response_event.audio.id  # type: ignore
                if model_response_event.audio.content is not None:
                    model_response.audio.content += model_response_event.audio.content  # type: ignore
                if model_response_event.audio.transcript is not None:
                    model_response.audio.transcript += model_response_event.audio.transcript  # type: ignore
                if model_response_event.audio.expires_at is not None:
                    model_response.audio.expires_at = model_response_event.audio.expires_at  # type: ignore
                if model_response_event.audio.mime_type is not None:
                    model_response.audio.mime_type = model_response_event.audio.mime_type  # type: ignore
                model_response.audio.sample_rate = model_response_event.audio.sample_rate
                model_response.audio.channels = model_response_event.audio.channels

                # Yield the audio and transcript bit by bit
                run_response.response_audio = AudioResponse(
                    id=model_response_event.audio.id,
                    content=model_response_event.audio.content,
                    transcript=model_response_event.audio.transcript,
                    sample_rate=model_response_event.audio.sample_rate,
                    channels=model_response_event.audio.channels,
                )
                run_response.created_at = model_response_event.created_at

                yield self._handle_event(
                    create_run_response_content_event(
                        from_run_response=run_response,
                        response_audio=run_response.response_audio,
                    ),
                    run_response,
                )

            if model_response_event.image is not None:
                self.add_image(model_response_event.image)

                yield self._handle_event(
                    create_run_response_content_event(
                        from_run_response=run_response,
                        image=model_response_event.image,
                    ),
                    run_response,
                )

        # Handle tool interruption events
        elif model_response_event.event == ModelResponseEvent.tool_call_paused.value:
            # Add tool calls to the run_response
            tool_executions_list = model_response_event.tool_executions
            if tool_executions_list is not None:
                # Add tool calls to the agent.run_response
                if run_response.tools is None:
                    run_response.tools = tool_executions_list
                else:
                    run_response.tools.extend(tool_executions_list)

                # Format tool calls whenever new ones are added during streaming
                run_response.formatted_tool_calls = format_tool_calls(run_response.tools)
        # If the model response is a tool_call_started, add the tool call to the run_response
        elif (
            model_response_event.event == ModelResponseEvent.tool_call_started.value
        ):  # Add tool calls to the run_response
            tool_executions_list = model_response_event.tool_executions
            if tool_executions_list is not None:
                # Add tool calls to the agent.run_response
                if run_response.tools is None:
                    run_response.tools = tool_executions_list
                else:
                    run_response.tools.extend(tool_executions_list)

                # Format tool calls whenever new ones are added during streaming
                run_response.formatted_tool_calls = format_tool_calls(run_response.tools)

                # Yield each tool call started event
                for tool in tool_executions_list:
                    yield self._handle_event(
                        create_tool_call_started_event(from_run_response=run_response, tool=tool), run_response
                    )

        # If the model response is a tool_call_completed, update the existing tool call in the run_response
        elif model_response_event.event == ModelResponseEvent.tool_call_completed.value:
            reasoning_step: Optional[ReasoningStep] = None

            tool_executions_list = model_response_event.tool_executions
            if tool_executions_list is not None:
                # Update the existing tool call in the run_response
                if run_response.tools:
                    # Create a mapping of tool_call_id to index
                    tool_call_index_map = {
                        tc.tool_call_id: i for i, tc in enumerate(run_response.tools) if tc.tool_call_id is not None
                    }
                    # Process tool calls
                    for tool_call_dict in tool_executions_list:
                        tool_call_id = tool_call_dict.tool_call_id or ""
                        index = tool_call_index_map.get(tool_call_id)
                        if index is not None:
                            run_response.tools[index] = tool_call_dict
                else:
                    run_response.tools = tool_executions_list

                # Only iterate through new tool calls
                for tool_call in tool_executions_list:
                    tool_name = tool_call.tool_name or ""
                    if tool_name.lower() in ["think", "analyze"]:
                        tool_args = tool_call.tool_args or {}

                        reasoning_step = self.update_reasoning_content_from_tool_call(tool_name, tool_args)

                        metrics = tool_call.metrics
                        if metrics is not None and metrics.time is not None:
                            reasoning_state["reasoning_time_taken"] = reasoning_state[
                                "reasoning_time_taken"
                            ] + float(metrics.time)
                    yield self._handle_event(
                        create_tool_call_completed_event(
                            from_run_response=run_response, tool=tool_call, content=model_response_event.content
                        ),
                        run_response,
                    )

            if stream_intermediate_steps:
                if reasoning_step is not None:
                    if not reasoning_state["reasoning_started"]:
                        yield self._handle_event(
                            create_reasoning_started_event(from_run_response=run_response), run_response
                        )
                        reasoning_state["reasoning_started"] = True

                    yield self._handle_event(
                        create_reasoning_step_event(
                            from_run_response=run_response,
                            reasoning_step=reasoning_step,
                            reasoning_content=run_response.reasoning_content or "",
                        ),
                        run_response,
                    )

def _get_json_output_prompt(self) -> str:
    """Return the JSON output prompt for the Agent.

    This is added to the system prompt when the response_model is set and structured_outputs is False.
    """
    import json

    json_output_prompt = "Provide your output as a JSON containing the following fields:"
    if self.response_model is not None:
        if isinstance(self.response_model, str):
            json_output_prompt += "\n<json_fields>"
            json_output_prompt += f"\n{self.response_model}"
            json_output_prompt += "\n</json_fields>"
        elif isinstance(self.response_model, list):
            json_output_prompt += "\n<json_fields>"
            json_output_prompt += f"\n{json.dumps(self.response_model)}"
            json_output_prompt += "\n</json_fields>"
        elif issubclass(self.response_model, BaseModel):
            json_schema = self.response_model.model_json_schema()
            if json_schema is not None:
                response_model_properties = {}
                json_schema_properties = json_schema.get("properties")
                if json_schema_properties is not None:
                    for field_name, field_properties in json_schema_properties.items():
                        formatted_field_properties = {
                            prop_name: prop_value
                            for prop_name, prop_value in field_properties.items()
                            if prop_name != "title"
                        }
                        response_model_properties[field_name] = formatted_field_properties
                json_schema_defs = json_schema.get("$defs")
                if json_schema_defs is not None:
                    response_model_properties["$defs"] = {}
                    for def_name, def_properties in json_schema_defs.items():
                        def_fields = def_properties.get("properties")
                        formatted_def_properties = {}
                        if def_fields is not None:
                            for field_name, field_properties in def_fields.items():
                                formatted_field_properties = {
                                    prop_name: prop_value
                                    for prop_name, prop_value in field_properties.items()
                                    if prop_name != "title"
                                }
                                formatted_def_properties[field_name] = formatted_field_properties
                        if len(formatted_def_properties) > 0:
                            response_model_properties["$defs"][def_name] = formatted_def_properties

                if len(response_model_properties) > 0:
                    json_output_prompt += "\n<json_fields>"
                    json_output_prompt += (
                        f"\n{json.dumps([key for key in response_model_properties.keys() if key != '$defs'])}"
                    )
                    json_output_prompt += "\n</json_fields>"
                    json_output_prompt += "\n\nHere are the properties for each field:"
                    json_output_prompt += "\n<json_field_properties>"
                    json_output_prompt += f"\n{json.dumps(response_model_properties, indent=2)}"
                    json_output_prompt += "\n</json_field_properties>"
        else:
            log_warning(f"Could not build json schema for {self.response_model}")
    else:
        json_output_prompt += "Provide the output as JSON."

    json_output_prompt += "\nStart your response with `{` and end it with `}`."
    json_output_prompt += "\nYour output will be passed to json.loads() to convert it to a Python object."
    json_output_prompt += "\nMake sure it only contains valid JSON."
    return json_output_prompt

def _get_member_id(self, member: Union[Agent, "Team"]) -> str:
    """
    Get the ID of a member
    """
    if isinstance(member, Agent) and member.agent_id is not None and (not is_valid_uuid(member.agent_id)):
        url_safe_member_id = url_safe_string(member.agent_id)
    elif isinstance(member, Team) and member.team_id is not None and (not is_valid_uuid(member.team_id)):
        url_safe_member_id = url_safe_string(member.team_id)
    elif member.name is not None:
        url_safe_member_id = url_safe_string(member.name)
    else:
        url_safe_member_id = None
    return url_safe_member_id

def should_update_memory(self, input: str) -> bool:
    """Determines if a message should be added to the memory db."""
    from agno.memory.classifier import MemoryClassifier

    if self.classifier is None:
        self.classifier = MemoryClassifier()

    self.classifier.existing_memories = self.memories
    classifier_response = self.classifier.run(input)
    if classifier_response.lower() == "yes":
        return True
    return False

async def async_load_documents(
    self,
    documents: List[Document],
    upsert: bool = False,
    skip_existing: bool = True,
    filters: Optional[Dict[str, Any]] = None,
) -> None:
    """Load documents to the knowledge base

    Args:
        documents (List[Document]): List of documents to load
        upsert (bool): If True, upserts documents to the vector db. Defaults to False.
        skip_existing (bool): If True, skips documents which already exist in the vector db when inserting. Defaults to True.
        filters (Optional[Dict[str, Any]]): Filters to add to each row that can be used to limit results during querying. Defaults to None.
    """
    self._aload_init(recreate=False, upsert=upsert)
    if self.vector_db is None:
        return

    log_info("Loading knowledge base")

    # Upsert documents if upsert is True
    if upsert and self.vector_db.upsert_available():
        try:
            await self.vector_db.async_upsert(documents=documents, filters=filters)
        except NotImplementedError:
            logger.warning("Vector db does not support async upsert")
            self.vector_db.upsert(documents=documents, filters=filters)
        log_info(f"Loaded {len(documents)} documents to knowledge base")
    else:
        # Filter out documents which already exist in the vector db
        if skip_existing:
            try:
                # Parallelize existence checks using asyncio.gather
                existence_checks = await asyncio.gather(
                    *[self.vector_db.async_doc_exists(document) for document in documents], return_exceptions=True
                )

                documents_to_load = [
                    doc
                    for doc, exists in zip(documents, existence_checks)
                    if not (isinstance(exists, bool) and exists)
                ]
            except NotImplementedError:
                logger.warning("Vector db does not support async doc_exists")
                documents_to_load = [document for document in documents if not self.vector_db.doc_exists(document)]
        else:
            documents_to_load = documents

        # Insert documents
        if len(documents_to_load) > 0:
            try:
                await self.vector_db.async_insert(documents=documents_to_load, filters=filters)
            except NotImplementedError:
                logger.warning("Vector db does not support async insert")
                self.vector_db.insert(documents=documents_to_load, filters=filters)
            log_info(f"Loaded {len(documents_to_load)} documents to knowledge base")
        else:
            log_info("No new documents to load")

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

