def _parse_response_content(
    self,
    run_response: Union[TeamRunResponse, RunResponse],
    tags_to_include_in_markdown: Set[str],
    show_markdown: bool = True,
) -> Any:
    from rich.json import JSON
    from rich.markdown import Markdown

    if isinstance(run_response.content, str):
        if show_markdown:
            escaped_content = escape_markdown_tags(run_response.content, tags_to_include_in_markdown)
            return Markdown(escaped_content)
        else:
            return run_response.get_content_as_string(indent=4)
    elif isinstance(run_response.content, BaseModel):
        try:
            return JSON(run_response.content.model_dump_json(exclude_none=True), indent=2)
        except Exception as e:
            log_warning(f"Failed to convert response to JSON: {e}")
    else:
        try:
            return JSON(json.dumps(run_response.content), indent=4)
        except Exception as e:
            log_warning(f"Failed to convert response to JSON: {e}")

def determine_tools_for_model(self, model: Model, tools: List[Union[Function, Callable, Toolkit, Dict]]) -> None:
    if self._tools_for_model is None:
        self._functions_for_model = {}
        self._tools_for_model = []

        # Get Agent tools
        if len(tools) > 0:
            log_debug("Processing tools for model")

            # Check if we need strict mode for the model
            strict = False
            if (
                self.response_model is not None
                and not self.use_json_mode
                and model.supports_native_structured_outputs
            ):
                strict = True

            for tool in tools:
                if isinstance(tool, Dict):
                    # If a dict is passed, it is a builtin tool
                    # that is run by the model provider and not the Agent
                    self._tools_for_model.append(tool)
                    log_debug(f"Included builtin tool {tool}")

                elif isinstance(tool, Toolkit):
                    # For each function in the toolkit and process entrypoint
                    for name, func in tool.functions.items():
                        # If the function does not exist in self.functions
                        if name not in self._functions_for_model:
                            func._agent = self
                            func._team = self
                            func.process_entrypoint(strict=strict)
                            if strict:
                                func.strict = True
                            if self.tool_hooks:
                                func.tool_hooks = self.tool_hooks
                            self._functions_for_model[name] = func
                            self._tools_for_model.append({"type": "function", "function": func.to_dict()})
                            log_debug(f"Added tool {name} from {tool.name}")

                    # Add instructions from the toolkit
                    if tool.add_instructions and tool.instructions is not None:
                        if self._tool_instructions is None:
                            self._tool_instructions = []
                        self._tool_instructions.append(tool.instructions)

                elif isinstance(tool, Function):
                    if tool.name not in self._functions_for_model:
                        tool._agent = self
                        tool._team = self
                        tool.process_entrypoint(strict=strict)
                        if strict and tool.strict is None:
                            tool.strict = True
                        if self.tool_hooks:
                            tool.tool_hooks = self.tool_hooks
                        self._functions_for_model[tool.name] = tool
                        self._tools_for_model.append({"type": "function", "function": tool.to_dict()})
                        log_debug(f"Added tool {tool.name}")

                    # Add instructions from the Function
                    if tool.add_instructions and tool.instructions is not None:
                        if self._tool_instructions is None:
                            self._tool_instructions = []
                        self._tool_instructions.append(tool.instructions)

                elif callable(tool):
                    # We add the tools, which are callable functions
                    try:
                        func = Function.from_callable(tool, strict=strict)
                        func._agent = self
                        func._team = self
                        if strict:
                            func.strict = True
                        if self.tool_hooks:
                            func.tool_hooks = self.tool_hooks
                        self._functions_for_model[func.name] = func
                        self._tools_for_model.append({"type": "function", "function": func.to_dict()})
                        log_debug(f"Added tool {func.name}")
                    except Exception as e:
                        log_warning(f"Could not add tool {tool}: {e}")

def _get_user_message(
    self,
    message: Optional[Union[str, List, Dict, Message]] = None,
    audio: Optional[Sequence[Audio]] = None,
    images: Optional[Sequence[Image]] = None,
    videos: Optional[Sequence[Video]] = None,
    files: Optional[Sequence[File]] = None,
    knowledge_filters: Optional[Dict[str, Any]] = None,
    **kwargs,
):
    # Get references from the knowledge base to use in the user message
    references = None
    self.run_response = cast(RunResponse, self.run_response)
    if self.add_references and message:
        message_str: str
        if isinstance(message, str):
            message_str = message
        elif callable(message):
            message_str = message(agent=self)
        else:
            raise Exception("message must be a string or a callable when add_references is True")

        try:
            retrieval_timer = Timer()
            retrieval_timer.start()
            docs_from_knowledge = self.get_relevant_docs_from_knowledge(
                query=message_str, filters=knowledge_filters, **kwargs
            )
            if docs_from_knowledge is not None:
                references = MessageReferences(
                    query=message_str, references=docs_from_knowledge, time=round(retrieval_timer.elapsed, 4)
                )
                # Add the references to the run_response
                if self.run_response.extra_data is None:
                    self.run_response.extra_data = RunResponseExtraData()
                if self.run_response.extra_data.references is None:
                    self.run_response.extra_data.references = []
                self.run_response.extra_data.references.append(references)
            retrieval_timer.stop()
            log_debug(f"Time to get references: {retrieval_timer.elapsed:.4f}s")
        except Exception as e:
            log_warning(f"Failed to get references: {e}")

    # Build user message if message is None, str or list
    user_message_content: str = ""
    if isinstance(message, str) or isinstance(message, list):
        if self.add_state_in_messages:
            if isinstance(message, str):
                user_message_content = self._format_message_with_state_variables(message)
            elif isinstance(message, list):
                user_message_content = "\n".join(
                    [self._format_message_with_state_variables(msg) for msg in message]
                )
        else:
            if isinstance(message, str):
                user_message_content = message
            else:
                user_message_content = "\n".join(message)

        # Add references to user message
        if (
            self.add_references
            and references is not None
            and references.references is not None
            and len(references.references) > 0
        ):
            user_message_content += "\n\nUse the following references from the knowledge base if it helps:\n"
            user_message_content += "<references>\n"
            user_message_content += self._convert_documents_to_string(references.references) + "\n"
            user_message_content += "</references>"
        # Add context to user message
        if self.add_context and self.context is not None:
            user_message_content += "\n\n<context>\n"
            user_message_content += self._convert_context_to_string(self.context) + "\n"
            user_message_content += "</context>"

        return Message(
            role="user",
            content=user_message_content,
            audio=audio,
            images=images,
            videos=videos,
            files=files,
            **kwargs,
        )

    # Build the default user message for the Agent
    elif message is None:
        # If we have any media, return a message with empty content
        if images is not None or audio is not None or videos is not None or files is not None:
            return Message(
                role="user",
                content="",
                images=images,
                audio=audio,
                videos=videos,
                files=files,
                **kwargs,
            )
        else:
            # If the message is None, return None
            return None

    # If message is provided as a Message, use it directly
    elif isinstance(message, Message):
        return message
    # If message is provided as a dict, try to validate it as a Message
    elif isinstance(message, dict):
        try:
            return Message.model_validate(message)
        except Exception as e:
            log_warning(f"Failed to validate message: {e}")

