            ):
                res.append(
                    os.path.join(
                        f"{directory or config.workspace_root}", item[path_str]
                    )
                )
            else:
                raise Exception(f"No such file or directory: {item[path_str]}")
        return res

    async def add_insights(
        self, json_info: list[dict[str, str]], output_type: str
    ) -> str:
