def tok_encode(
    self,
    string: str,
    left_truncate_len: int | None = None,
    add_special_tokens: bool | None = None,
) -> list[int]:
    """ """
    # default for None - empty dict, use predefined tokenizer param
    # used for all models except for CausalLM or predefined value
    special_tokens_kwargs = {}

    # by default for CausalLM - false or self.add_bos_token is set
    if add_special_tokens is None:
        if self.backend == "causal":
            special_tokens_kwargs = {
                "add_special_tokens": False or self.add_bos_token
            }
    # otherwise the method explicitly defines the value
    else:
        special_tokens_kwargs = {"add_special_tokens": add_special_tokens}

    encoding = self.tokenizer.encode(string, **special_tokens_kwargs)

    # left-truncate the encoded context to be at most `left_truncate_len` tokens long
    if left_truncate_len:
        encoding = encoding[-left_truncate_len:]

    return encoding

def tok_batch_encode(
    self,
    strings: list[str],
    padding_side: str = "left",
    left_truncate_len: int | None = None,
    truncation: bool = False,
) -> tuple[torch.Tensor, torch.Tensor]:
    # encode a batch of strings. converts to tensors and pads automatically, unlike tok_encode.
    old_padding_side = self.tokenizer.padding_side
    self.tokenizer.padding_side = padding_side

    add_special_tokens = {}
    if self.backend == "causal":
        add_special_tokens = {"add_special_tokens": False or self.add_bos_token}

    encoding = self.tokenizer(
        strings,
        truncation=truncation,
        padding="longest",
        return_tensors="pt",
        **add_special_tokens,
    )
    if left_truncate_len:
        original_lengths = encoding["input_ids"].size(1)
        if original_lengths > left_truncate_len:
            eval_logger.warning(
                f"Left truncation applied. Original sequence length was {original_lengths}, "
                f"truncating to last {left_truncate_len} tokens. Some content will be lost.",
            )
        encoding["input_ids"] = encoding["input_ids"][:, -left_truncate_len:]
        encoding["attention_mask"] = encoding["attention_mask"][
            :, -left_truncate_len:
        ]
    self.tokenizer.padding_side = old_padding_side

    return encoding["input_ids"], encoding["attention_mask"]

def _create_model(
    self,
    pretrained: str,
    revision: str | None = "main",
    dtype: str | torch.dtype | None = "auto",
    trust_remote_code: bool | None = False,
    # arguments used for splitting a model across GPUs naively.
    # only used if `parallelize=True`.
    # (accelerate naive PP (device_map) options)
    parallelize: bool | None = False,
    gpus: int | None = None,
    max_memory_per_gpu: int | str | None = None,
    max_cpu_memory: int | str | None = None,
    offload_folder: str | None = "./offload",
    # PEFT, delta weights and quantization options
    peft: str | None = None,
    delta: str | None = None,
    autogptq: bool | str | None = False,
    gptqmodel: bool | None = False,
    gguf_file: str | None = None,
    quantization_config: AutoQuantizationConfig | None = None,
    subfolder: str = "",
    **kwargs,
) -> None:
    """Initializes an HF or HF-compatible PreTrainedModel from scratch
    inside HFLM, using the kwargs passed into self.__init__().

    Also handles functionality such as AutoGPTQ usage and PEFT wrapping.

    For future similar extensions to AutoGPTQ that are not core to HF's ecosystem,
    (such as PyTorch models that are nearly, but not quite, fully mirroring
    HF's public interface relied on in this HFLM class)
    please consider subclassing HFLM and overriding this and other methods as needed.
    """

    model_kwargs = kwargs or {}

    model_kwargs.update(
        self._get_accelerate_args(
            parallelize=parallelize,
            device_map=kwargs.get("device_map"),
            max_memory_per_gpu=max_memory_per_gpu,
            max_cpu_memory=max_cpu_memory,
            offload_folder=offload_folder,
            gpus=gpus,
        )
    )

    if not autogptq and not gptqmodel:
        if model_kwargs.get("load_in_4bit"):
            assert vparse(transformers.__version__) >= vparse("4.30.0"), (
                "load_in_4bit requires transformers >= 4.30.0"
            )
            if compute_dtype := model_kwargs.get("bnb_4bit_compute_dtype"):
                model_kwargs["bnb_4bit_compute_dtype"] = get_dtype(compute_dtype)

        self._model = self.AUTO_MODEL_CLASS.from_pretrained(
            pretrained,
            revision=revision,
            torch_dtype=get_dtype(dtype),
            trust_remote_code=trust_remote_code,
            gguf_file=gguf_file,
            quantization_config=quantization_config,
            subfolder=subfolder,
            **model_kwargs,
        )
    else:
        if autogptq and gptqmodel:
            raise ValueError(
                "Cannot use both 'autogptq' and 'gptqmodel' options at the same time."
            )

        if autogptq:
            try:
                from auto_gptq import AutoGPTQForCausalLM
            except ModuleNotFoundError as exception:
                raise type(exception)(
                    "Tried to load auto_gptq, but auto-gptq is not installed ",
                    "please install auto-gptq via pip install lm-eval[gptq] or pip install -e .[gptq]",
                ) from exception

            self._model = AutoGPTQForCausalLM.from_quantized(
                pretrained,
                trust_remote_code=trust_remote_code,
                model_basename=None if autogptq is True else Path(autogptq).stem,
                use_safetensors=True
                if autogptq is True
                else autogptq.endswith(".safetensors"),
                **model_kwargs,
            )

        if gptqmodel:
            try:
                from gptqmodel import GPTQModel
            except ModuleNotFoundError as exception:
                raise type(exception)(
                    "Tried to load gptqmodel, but gptqmodel is not installed ",
                    "please install gptqmodel via `pip install gptqmodel --no-build-isolation` or `pip install lm-eval[gptqmodel] --no-build-isolation`",
                ) from exception

            self._model = GPTQModel.from_quantized(
                pretrained, trust_remote_code=trust_remote_code, **model_kwargs
            )

    if peft and delta:
        raise ValueError(
            "Cannot use both 'peft' and 'delta' options at the same time."
        )

    if peft:
        from peft import PeftModel
        from peft import __version__ as PEFT_VERSION

        if model_kwargs.get("load_in_4bit") and vparse(PEFT_VERSION) < vparse(
            "0.4.0"
        ):
            raise AssertionError("load_in_4bit requires peft >= 0.4.0")

        # Compatible with Gemma3 (multimodal) and old models
        if hasattr(self._model.config, "text_config") and hasattr(self._model.config.text_config, "vocab_size"):
            vocab_size = self._model.config.text_config.vocab_size
        else:
            vocab_size = self._model.config.vocab_size

        if vocab_size != len(self.tokenizer):
            # resize model for LoRAs with added tokens
            eval_logger.info(
                f"Model config indicates vocab_size='{vocab_size}', but found tokenizer with vocab size '{len(self.tokenizer)}'. Resizing model embedding layer..."
            )
            self._model.resize_token_embeddings(len(self.tokenizer))
        self._model = PeftModel.from_pretrained(
            self._model, peft, revision=revision
        )
    elif delta:
        if autogptq:
            eval_logger.warning(
                "Delta weights might trigger unexpected behavior when used with AutoGPTQ."
            )
        _model_delta = self.AUTO_MODEL_CLASS.from_pretrained(
            delta,
            revision=revision,
            torch_dtype=get_dtype(dtype),
            trust_remote_code=trust_remote_code,
            **model_kwargs,
        )
        for name, param in self._model.state_dict().items():
            try:
                param.data += _model_delta.state_dict()[name]
            except KeyError as e:
                raise KeyError(
                    f"Delta model is missing weights for layer: {name}"
                ) from e
            except Exception as e:
                raise RuntimeError(
                    f"Failed to add delta weights to layer {name}. Error: {e}"
                ) from e

        del _model_delta

def numeric_match(prediction: str, ground_truth: str, tolerance: float = 0.001) -> float:
    """Check if prediction matches a numeric answer within tolerance."""
    try:
        # Extract numbers from both strings
        pred_nums = re.findall(r'-?\d+\.?\d*', extract_answer(prediction))
        truth_nums = re.findall(r'-?\d+\.?\d*', ground_truth)

        if not pred_nums or not truth_nums:
            # Fall back to exact match if no numbers found
            return exact_match(prediction, ground_truth)

        pred_num = float(pred_nums[0])
        truth_num = float(truth_nums[0])

        return 1.0 if abs(pred_num - truth_num) < tolerance else 0.0
    except:
        # Fall back to exact match if parsing fails
        return exact_match(prediction, ground_truth)

def count_score(prediction, ground_truth):
    """Score for counting tasks."""
    try:
        # Extract the first number from prediction
        numbers = re.findall(r'\d+', prediction)
        if not numbers:
            return 0.0
        pred_count = int(numbers[0])
        true_count = int(ground_truth)
        return 1.0 if pred_count == true_count else 0.0
    except:
        return 0.0

def _build_date_trunc(args: t.List[exp.Expression]) -> exp.Expression:
    a0, a1 = seq_get(args, 0), seq_get(args, 1)

    def _is_unit_like(e: exp.Expression | None) -> bool:
        if not (isinstance(e, exp.Literal) and e.is_string):
            return False
        text = e.this
        return not any(ch.isdigit() for ch in text)

    # Determine which argument is the unit
    unit, this = a0, a1 if _is_unit_like(a0) else a1, a0

    return exp.TimestampTrunc(this=this, unit=unit)

