    keys = self.bot.config.public_keys

    if key in keys:
        try:
            await self.bot.config.set(key, value)
            await self.bot.config.update()
            embed = discord.Embed(
                title="Success",
                color=self.bot.main_color,
                description=f"Set `{key}` to `{self.bot.config[key]}`.",
