def _resample_series(
    series,
    start,
    end,
    reindex_closed,
    rule,
    resample_kwargs,
    how,
    fill_value,
    how_args,
    how_kwargs,
):
    out = getattr(series.resample(rule, **resample_kwargs), how)(
        *how_args, **how_kwargs
    )
    if reindex_closed is None:
        inclusive = "both"
    else:
        inclusive = reindex_closed
    closed_kwargs = {"inclusive": inclusive}

    new_index = pd.date_range(
        start.tz_localize(None),
        end.tz_localize(None),
        freq=rule,
        **closed_kwargs,
        name=out.index.name,
        unit=out.index.unit,
    ).tz_localize(start.tz, nonexistent="shift_forward")

    if not out.index.isin(new_index).all():
        raise ValueError(
            "Index is not contained within new index. This can often be "
            "resolved by using larger partitions, or unambiguous "
            "frequencies: 'Q', 'A'..."
        )

    return out.reindex(new_index, fill_value=fill_value)

def _resample_bin_and_out_divs(divisions, rule, closed="left", label="left"):
    rule = pd.tseries.frequencies.to_offset(rule)
    g = pd.Grouper(freq=rule, how="count", closed=closed, label=label)

    # Determine bins to apply `how` to. Disregard labeling scheme.
    divs = pd.Series(range(len(divisions)), index=divisions)
    temp = divs.resample(rule, closed=closed, label="left").count()
    tempdivs = temp.loc[temp > 0].index

    # Cleanup closed == 'right' and label == 'right'
    res = pd.offsets.Nano() if isinstance(rule, pd.offsets.Tick) else pd.offsets.Day()
    if g.closed == "right":
        newdivs = tempdivs + res
    else:
        newdivs = tempdivs
    if g.label == "right":
        outdivs = tempdivs + rule
    else:
        outdivs = tempdivs

    newdivs = methods.tolist(newdivs)
    outdivs = methods.tolist(outdivs)

    # Adjust ends
    if newdivs[0] < divisions[0]:
        newdivs[0] = divisions[0]
    if newdivs[-1] < divisions[-1]:
        if len(newdivs) < len(divs):
            setter = lambda a, val: a.append(val)
        else:
            setter = lambda a, val: a.__setitem__(-1, val)
        setter(newdivs, divisions[-1] + res)
        if outdivs[-1] > divisions[-1]:
            setter(outdivs, outdivs[-1])
        elif outdivs[-1] < divisions[-1]:
            setter(outdivs, temp.index[-1])

    return tuple(map(pd.Timestamp, newdivs)), tuple(map(pd.Timestamp, outdivs))

def initialize_write(
    cls,
    df,
    fs,
    path,
    append=False,
    partition_on=None,
    ignore_divisions=False,
    division_info=None,
    schema="infer",
    index_cols=None,
    **kwargs,
):
    if schema == "infer" or isinstance(schema, dict):
        # Start with schema from _meta_nonempty
        inferred_schema = pyarrow_schema_dispatch(
            df._meta_nonempty.set_index(index_cols)
            if index_cols
            else df._meta_nonempty
        ).remove_metadata()

        # Use dict to update our inferred schema
        if isinstance(schema, dict):
            schema = pa.schema(schema)
            for name in schema.names:
                i = inferred_schema.get_field_index(name)
                j = schema.get_field_index(name)
                inferred_schema = inferred_schema.set(i, schema.field(j))
        schema = inferred_schema

    # Check that target directory exists
    fs.mkdirs(path, exist_ok=True)
    if append and division_info is None:
        ignore_divisions = True

    full_metadata = None  # metadata for the full dataset, from _metadata
    tail_metadata = None  # metadata for at least the last file in the dataset
    i_offset = 0
    metadata_file_exists = False
    if append:
        # Extract metadata and get file offset if appending
        ds = pa_ds.dataset(path, filesystem=_wrapped_fs(fs), format="parquet")
        i_offset = len(ds.files)
        if i_offset > 0:
            try:
                with fs.open(fs.sep.join([path, "_metadata"]), mode="rb") as fil:
                    full_metadata = pq.read_metadata(fil)
                tail_metadata = full_metadata
                metadata_file_exists = True
            except OSError:
                try:
                    with fs.open(
                        sorted(ds.files, key=natural_sort_key)[-1], mode="rb"
                    ) as fil:
                        tail_metadata = pq.read_metadata(fil)
                except OSError:
                    pass
        else:
            append = False  # No existing files, can skip the append logic

    # If appending, validate against the initial metadata file (if present)
    if append and tail_metadata is not None:
        arrow_schema = tail_metadata.schema.to_arrow_schema()
        names = arrow_schema.names
        has_pandas_metadata = (
            arrow_schema.metadata is not None and b"pandas" in arrow_schema.metadata
        )
        if has_pandas_metadata:
            pandas_metadata = json.loads(
                arrow_schema.metadata[b"pandas"].decode("utf8")
            )
            categories = [
                c["name"]
                for c in pandas_metadata["columns"]
                if c["pandas_type"] == "categorical"
            ]
        else:
            categories = None
        dtypes = _get_pyarrow_dtypes(arrow_schema, categories)
        if set(names) != set(df.columns) - set(partition_on):
            raise ValueError(
                "Appended columns not the same.\n"
                "Previous: {} | New: {}".format(names, list(df.columns))
            )
        elif pd.Series(dtypes).loc[names].tolist() != df[names].dtypes.tolist():
            # TODO Coerce values for compatible but different dtypes
            raise ValueError(
                "Appended dtypes differ.\n{}".format(
                    set(dtypes.items()) ^ set(df.dtypes.items())
                )
            )

        # Check divisions if necessary
        if division_info["name"] not in names:
            ignore_divisions = True
        if not ignore_divisions:
            old_end = None
            row_groups = (
                tail_metadata.row_group(i)
                for i in range(tail_metadata.num_row_groups)
            )
            index_col_i = names.index(division_info["name"])
            for row_group in row_groups:
                column = row_group.column(index_col_i)
                if column.statistics:
                    if old_end is None:
                        old_end = column.statistics.max
                    elif column.statistics.max > old_end:
                        old_end = column.statistics.max
                    else:
                        # Existing column on disk isn't sorted, set
                        # `old_end = None` to skip check below
                        old_end = None
                        break

            divisions = division_info["divisions"]
            if old_end is not None and divisions[0] <= old_end:
                raise ValueError(
                    "The divisions of the appended dataframe overlap with "
                    "previously written divisions. If this is desired, set "
                    "``ignore_divisions=True`` to append anyway.\n"
                    "- End of last written partition: {old_end}\n"
                    "- Start of first new partition: {divisions[0]}"
                )

    extra_write_kwargs = {"schema": schema, "index_cols": index_cols}
    return i_offset, full_metadata, metadata_file_exists, extra_write_kwargs

def assert_dask_dtypes(ddf, res, numeric_equal=True):
    """Check that the dask metadata matches the result.

    If `numeric_equal`, integer and floating dtypes compare equal. This is
    useful due to the implicit conversion of integer to floating upon
    encountering missingness, which is hard to infer statically."""

    eq_type_sets = [{"O", "S", "U", "a"}]  # treat object and strings alike
    if numeric_equal:
        eq_type_sets.append({"i", "f", "u"})

    def eq_dtypes(a, b):
        return any(
            a.kind in eq_types and b.kind in eq_types for eq_types in eq_type_sets
        ) or (a == b)

    if not is_dask_collection(res) and is_dataframe_like(res):
        for a, b in pd.concat([ddf._meta.dtypes, res.dtypes], axis=1).itertuples(
            index=False
        ):
            assert eq_dtypes(a, b)
    elif not is_dask_collection(res) and (is_index_like(res) or is_series_like(res)):
        a = ddf._meta.dtype
        b = res.dtype
        assert eq_dtypes(a, b)
    else:
        if hasattr(ddf._meta, "dtype"):
            a = ddf._meta.dtype
            if not hasattr(res, "dtype"):
                assert np.isscalar(res)
                b = np.dtype(type(res))
            else:
                b = res.dtype
            assert eq_dtypes(a, b)
        else:
            assert type(ddf._meta) == type(res)

