def merge_locustfiles_content(
    locustfiles: list[str],
) -> tuple[
    dict[str, type[locust.User]],
    dict[str, locust.LoadTestShape],
    dict[str, list[locust.TaskSet | Callable]],
    locust.LoadTestShape | None,
]:
    """
    Validate content of each locustfile in locustfiles and merge data to single objects output.

    Can stop locust execution on errors.
    """
    available_user_classes: dict[str, type[locust.User]] = {}
    available_shape_classes: dict[str, locust.LoadTestShape] = {}
    # TODO: list[locust.TaskSet | Callable] should be replaced with correct type,
    #  supported by User class task attribute. This require additional rewrite,
    #  out of main refactoring.
    #  Check docs for real supported task attribute signature for User\TaskSet class.
    available_user_tasks: dict[str, list[locust.TaskSet | Callable]] = {}

    def set_available_things(user_classes, shape_classes):
        # Setting Available Shape Classes
        for _shape_class in shape_classes:
            shape_class_name = type(_shape_class).__name__
            if shape_class_name in available_shape_classes.keys():
                sys.stderr.write(f"Duplicate shape classes: {shape_class_name}\n")
                sys.exit(1)

            available_shape_classes[shape_class_name] = _shape_class

        # Setting Available User Classes
        for class_name, class_definition in user_classes.items():
            if class_name in available_user_classes.keys():
                previous_path = inspect.getfile(available_user_classes[class_name])
                new_path = inspect.getfile(class_definition)
                if previous_path == new_path:
                    # The same User class was defined in two locustfiles but one probably imported the other, so we just ignore it
                    continue
                else:
                    sys.stderr.write(
                        f"Duplicate user class names: {class_name} is defined in both {previous_path} and {new_path}\n"
                    )
                    sys.exit(1)

            available_user_classes[class_name] = class_definition
            available_user_tasks[class_name] = class_definition.tasks

    for _locustfile in locustfiles:
        user_classes, shape_classes = load_locustfile(_locustfile)
        set_available_things(user_classes, shape_classes)

    if not available_user_classes:  # only load pytest-based locustfiles if no regular ones were found
        for _locustfile in locustfiles:
            user_classes = load_locustfile_pytest(_locustfile)
            set_available_things(user_classes, [])

    shape_class = list(available_shape_classes.values())[0] if available_shape_classes else None

    return available_user_classes, available_shape_classes, available_user_tasks, shape_class

class TestProcess:
    """
    Wraps a subprocess for testing purposes.
    """

    __test__ = False

    def __init__(
        self,
        command: str,
        *,
        expect_return_code: int | None = 0,
        sigint_on_exit: bool = True,
        expect_timeout: int = 5,
        use_pty: bool = False,
        join_timeout: int = 1,
    ):
        self.proc: subprocess.Popen[str]
        self._terminated = False
        self._failed = False

        self.expect_return_code = expect_return_code
        self.expect_timeout = expect_timeout
        self.sigint_on_exit = sigint_on_exit
        self.join_timeout = join_timeout

        self.stderr_output: list[str] = []
        self.stdout_output: list[str] = []
        self._stderr_cursor: int = 0  # Used for stateful log matching
        self._stdout_cursor: int = 0

        self.use_pty: bool = use_pty
        # Create PTY pair
        if self.use_pty:
            if IS_WINDOWS:
                raise Exception("termios doesn't exist on windows, and thus we cannot import pty")

            import pty

            self.stdin_m, self.stdin_s = pty.openpty()

        self.proc = subprocess.Popen(
            shlex.split(command) if not IS_WINDOWS else command.split(" "),
            env={"PYTHONUNBUFFERED": "1", **os.environ},
            stdin=self.stdin_s if self.use_pty else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )

        def _consume_output(source: IO[str], to: list[str]):
            for line in iter(source.readline, ""):
                line = line.rstrip("\n")
                to.append(line)

        self.stdout_reader = gevent.spawn(_consume_output, self.proc.stdout, self.stdout_output)
        self.stderr_reader = gevent.spawn(_consume_output, self.proc.stderr, self.stderr_output)

    def on_fail(self, reason: str = ""):
        __tracebackhide__ = True
        if self._failed:
            return
        self._failed = True
        for line in self.stderr_output:
            print(line)
        pytest.fail(reason)

    def __enter__(self) -> "TestProcess":
        return self

    def __exit__(self, *_) -> None:
        self.close()

    def close(self) -> None:
        if self.use_pty:
            os.close(self.stdin_m)
            os.close(self.stdin_s)

        try:
            if self.sigint_on_exit and not self._terminated:
                self.terminate()
            proc_return_code = self.proc.wait(timeout=self.join_timeout)

            # Locust does not perform a graceful shutdown on Windows since we send SIGTERM
            if not IS_WINDOWS and self.expect_return_code is not None and proc_return_code != self.expect_return_code:
                self.on_fail(
                    f"Process exited with return code {proc_return_code}. Expected {self.expect_return_code} ({proc_return_code} != {self.expect_return_code})"
                )
        except subprocess.TimeoutExpired:
            self.proc.kill()
            self.proc.wait()
            self.on_fail(f"Process took more than {self.join_timeout} seconds to terminate.")

        self.stdout_reader.join(timeout=self.join_timeout)
        self.stderr_reader.join(timeout=self.join_timeout)

    # Check output logs from last found (stateful)
    def expect(self, to_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
            cursor = self._stdout_cursor
        else:
            buffer = self.stderr_output
            cursor = self._stderr_cursor

        start_time = time.time()
        while time.time() - start_time < self.expect_timeout:
            new_lines = buffer[cursor:]
            for idx, line in enumerate(new_lines):
                if to_expect in line:
                    cursor += idx + 1
                    return
            time.sleep(0.05)

        self.on_fail(f"Timed out waiting for '{to_expect}' after {self.expect_timeout} seconds. Got {buffer[-5:]}")

    # Check all output logs (stateless)
    def expect_any(self, to_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
        else:
            buffer = self.stderr_output

        if any(to_expect in line for line in buffer):
            return

        self.on_fail(f"Did not see expected message: '{to_expect}'. Got {buffer[-5:]}")

    def not_expect_any(self, to_not_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
        else:
            buffer = self.stderr_output

        if any(to_not_expect in line for line in buffer):
            self.on_fail(f"Found unexpected message: '{to_not_expect}'.")

    def send_input(self, content: str):
        if self.use_pty:
            os.write(self.stdin_m, content.encode())
        else:
            raise Exception("Cannot send input to proccess without pty.")

    def terminate(self):
        if IS_WINDOWS:
            # Signals are hard on Windows
            sig = signal.SIGTERM
        else:
            sig = signal.SIGINT

        self.proc.send_signal(sig)
        self._terminated = True

class FilterGroup:
    def __init__(self, label: str) -> None:
        self.label = label
        self.filters: list[dict] = []

    def append(self, filter: dict) -> None:
        self.filters.append(filter)

    def non_lazy(self) -> tuple[str, list[dict]]:
        filters = []
        for item in self.filters:
            copy = dict(item)
            copy["operation"] = as_unicode(copy["operation"])
            options = copy["options"]
            if options:
                copy["options"] = [(k, text_type(v)) for k, v in options]

            filters.append(copy)
        return as_unicode(self.label), filters

    def __iter__(self) -> t.Iterator[dict]:
        return iter(self.filters)

def _export_tablib(self, export_type: str, return_url: str) -> T_RESPONSE:
    """
    Exports a variety of formats using the tablib library.
    """
    if tablib is None:
        raise Exception(
            "Could not import `tablib`. "
            "Enable `export` integration by installing `flask-admin[export]`"
        )

    filename = self.get_export_name(export_type)

    disposition = f"attachment;filename={secure_filename(filename)}"

    mimetype, encoding = mimetypes.guess_type(filename)
    if not mimetype:
        mimetype = "application/octet-stream"
    if encoding:
        mimetype = f"{mimetype}; charset={encoding}"

    ds = tablib.Dataset(headers=[csv_encode(c[1]) for c in self._export_columns])

    count, data = self._export_data()

    for row in data:
        vals = [
            csv_encode(self.get_export_value(row, c[0]))
            for c in self._export_columns
        ]
        ds.append(vals)

    try:
        try:
            response_data = ds.export(format=export_type)
        except AttributeError:
            response_data = getattr(ds, export_type)
    except (AttributeError, tablib.UnsupportedFormat):
        flash(
            gettext('Export type "%(type)s" is not supported.', type=export_type),
            "error",
        )
        return redirect(return_url)

    return Response(
        response_data,
        headers={"Content-Disposition": disposition},
        mimetype=mimetype,
    )

class RedisCli(BaseView):
    """
    Simple redis console.

    To use it, simply pass `Redis` connection object to the constructor.
    """

    remapped_commands = {"del": "delete"}
    """
        List of redis remapped commands.
    """

    excluded_commands = set(("pubsub", "set_response_callback", "from_url"))
    """
        List of excluded commands.
    """

    def __init__(
        self,
        redis: T_REDIS,
        name: t.Optional[str] = None,
        category: t.Any = None,
        endpoint: t.Optional[str] = None,
        url: t.Optional[str] = None,
    ) -> None:
        """
        Constructor.

        :param redis:
            Redis connection
        :param name:
            View name. If not provided, will use the model class name
        :param category:
            View category
        :param endpoint:
            Base endpoint. If not provided, will use the model name + 'view'.
            For example if model name was 'User', endpoint will be
            'userview'
        :param url:
            Base URL. If not provided, will use endpoint as a URL.
        """
        super().__init__(name, category, endpoint, url)

        self.redis = redis

        self.commands: dict[str, t.Any] = {}

        self._inspect_commands()
        self._contribute_commands()

    def _inspect_commands(self) -> None:
        """
        Inspect connection object and extract command names.
        """
        for name in dir(self.redis):
            if not name.startswith("_"):
                attr = getattr(self.redis, name)
                if callable(attr) and name not in self.excluded_commands:
                    doc = (getattr(attr, "__doc__", "") or "").strip()
                    self.commands[name] = (attr, doc)

        for new, old in self.remapped_commands.items():
            self.commands[new] = self.commands[old]

    def _contribute_commands(self) -> None:
        """
        Contribute custom commands.
        """
        self.commands["help"] = (self._cmd_help, "Help!")

    def _execute_command(self, name: str, args: t.Any) -> str:
        """
        Execute single command.

        :param name:
            Command name (case-insensitive)
        :param args:
            Command arguments
        """
        name = name.lower() # make commands case-insensitive
        name = self.remapped_commands.get(name, name) # Do some remapping

        # Execute command
        if name not in self.commands:
            return self._error(gettext("Cli: Invalid command."))

        handler, _ = self.commands[name]
        return self._result(handler(*args))

    def _parse_cmd(self, cmd: str) -> tuple[str, ...]:
        """
        Parse command by using shlex module.

        :param cmd:
            Command to parse
        """
        return tuple(shlex.split(cmd))

    def _error(self, msg: str) -> str:
        """
        Format error message as HTTP response.

        :param msg:
            Message to format
        """
        return Markup(f'<div class="error">{msg}</div>')

    def _result(self, result: t.Any) -> str:
        """
        Format result message as HTTP response.

        :param msg:
            Result to format.
        """
        return self.render(
            "admin/rediscli/response.html",
            type_name=lambda d: type(d).__name__,
            result=result,
        )

    # Commands
    def _cmd_help(self, *args: str) -> TextWrapper:
        """
        Help command implementation.
        """
        if not args:
            help = "Usage: help <command>.\nList of supported commands: "
            help += ", ".join(n for n in sorted(self.commands))
            return TextWrapper(help)

        cmd = args[0]
        if cmd not in self.commands:
            raise CommandError("Invalid command.")

        help = self.commands[cmd][1]
        if not help:
            return TextWrapper("Command does not have any help.")

        return TextWrapper(help)

    # Views
    @expose("/")
    def console_view(self) -> str:
        """
        Console view.
        """
        return self.render("admin/rediscli/console.html")

    @expose("/run/", methods=("POST",))
    def execute_view(self) -> str:
        """
        AJAX API.
        """
        try:
            cmd = request.form.get("cmd")
            if not cmd:
                return self._error("Cli: Empty command.")

            parts = self._parse_cmd(cmd)
            if not parts:
                return self._error("Cli: Failed to parse command.")

            return self._execute_command(parts[0], parts[1:])
        except CommandError as err:
            return self._error(f"Cli: {err}")
        except Exception as ex:
            log.exception(ex)
            return self._error(f"Cli: {ex}")

def set_python_diagnostics(self, enabled: bool) -> None:
