        return None

class Item:
    def __init__(self, control, attrs, index=None):
        label = _get_label(attrs)
        self.__dict__.update({
            "name": attrs["value"],
            "_labels": label and [label] or [],
            "attrs": attrs,
            "_control": control,
            "disabled": "disabled" in attrs,
            "_selected": False,
            "id": attrs.get("id"),
            "_index": index,
            })
        control.items.append(self)

    def get_labels(self):
        """Return all labels (Label instances) for this item.

        For items that represent radio buttons or checkboxes, if the item was
        surrounded by a <label> tag, that will be the first label; all other
        labels, connected by 'for' and 'id', are in the order that appear in
        the HTML.

        For items that represent select options, if the option had a label
        attribute, that will be the first label.  If the option has contents
        (text within the option tags) and it is not the same as the label
        attribute (if any), that will be a label.  There is nothing in the
        spec to my knowledge that makes an option with an id unable to be the
        target of a label's for attribute, so those are included, if any, for
        the sake of consistency and completeness.

        """
        res = []
        res.extend(self._labels)
        if self.id:
            res.extend(self._control._form._id_to_labels.get(self.id, ()))
        return res

    def __getattr__(self, name):
        if name=="selected":
            return self._selected
        raise AttributeError(name)

    def __setattr__(self, name, value):
        if name == "selected":
            self._control._set_selected_state(self, value)
        elif name == "disabled":
            self.__dict__["disabled"] = bool(value)
        else:
            raise AttributeError(name)

    def __str__(self):
        res = self.name
        if self.selected:
            res = "*" + res
        if self.disabled:
            res = "(%s)" % res
        return res

    def __repr__(self):
        # XXX appending the attrs without distinguishing them from name and id
        # is silly
        attrs = [("name", self.name), ("id", self.id)]+self.attrs.items()
        return "<%s %s>" % (
            self.__class__.__name__,
            " ".join(["%s=%r" % (k, v) for k, v in attrs])
            )

def _get(self, name, by_label=False, nr=None, exclude_disabled=False):
    # strictly for use by deprecated methods
    if by_label:
        name, label = None, name
    else:
        name, label = name, None
    return self.get(name, label, nr, exclude_disabled)

def add_to_form(self, form):
    assert self._form is None or form == self._form, (
        "can't add control to more than one form")
    self._form = form
    if self.name is None:
        # always count nameless elements as separate controls
        Control.add_to_form(self, form)
    else:
        for ii in xrange(len(form.controls)-1, -1, -1):
            control = form.controls[ii]
            if control.name == self.name and control.type == self.type:
                if control._closed:
                    Control.add_to_form(self, form)
                else:
                    control.merge_control(self)
                break
        else:
            Control.add_to_form(self, form)

def _multiple_set_value(self, value):
    compat = self._form.backwards_compat
    turn_on = []  # transactional-ish
    turn_off = [item for item in self.items if
                item.selected and (not item.disabled or compat)]
    names = {}
    for nn in value:
        if nn in names.keys():
            names[nn] += 1
        else:
            names[nn] = 1
    for name, count in names.items():
        on, off = self._get_items(name, count)
        for i in xrange(count):
            if on:
                item = on[0]
                del on[0]
                del turn_off[turn_off.index(item)]
            else:
                item = off[0]
                del off[0]
                turn_on.append(item)
    for item in turn_off:
        item.selected = False
    for item in turn_on:
        item.selected = True

def _run_sqlmap(self):
    """Run sqlmap with current configuration"""
    config = {}

    # Collect all field values
    for tab in self.tabs:
        for option in tab['options']:
            dest = option['dest']
            value = option['value'] if option['value'] else option.get('default')

            if option['type'] == 'bool':
                config[dest] = bool(value)
            elif option['type'] == 'int':
                config[dest] = int(value) if value else None
            elif option['type'] == 'float':
                config[dest] = float(value) if value else None
            else:
                config[dest] = value

    # Set defaults for unset options
    for option in self.parser.option_list:
        if option.dest not in config or config[option.dest] is None:
            config[option.dest] = defaults.get(option.dest, None)

    # Create temp config file
    handle, configFile = tempfile.mkstemp(prefix=MKSTEMP_PREFIX.CONFIG, text=True)
    os.close(handle)

    saveConfig(config, configFile)

    # Show console
    self._show_console(configFile)

def report_validation_metrics(self, student, trainset, valset, logger, step_idx=-1):
    if step_idx == -1 or step_idx == self.num_train_steps - 1 or (step_idx + 1) % self.num_steps_for_val == 0:
        pass
    else:
        return

    if valset is not None:
        # Validation set provided by user
        assert not self.use_train_as_val, "If valset is provided, use_train_as_val must be False."
        assert isinstance(self.num_steps_for_val, int) and self.num_steps_for_val > 0, "num_steps_for_val must be a positive integer."
        if self.report_train_scores:
            if step_idx == -1:
                logger.info("Using user provided validation set and reporting train scores for every validation step in addition.")
            valset_evaluator = Evaluate(
                devset=valset + trainset,
                num_threads=self.num_threads,
                display_progress=True,
                provide_traceback=False,  # TODO(check with team)
                max_errors=len(valset)*10,  # TODO(check with team)
                failure_score=self.failure_score
            )
            if step_idx == -1:
                logger.info("Evaluating the student program on the train+validation set before training loop...")
            else:
                logger.info(f"Evaluating the student program on the validation set after training step {step_idx + 1}/{self.num_train_steps}")
            valset_evaluation = valset_evaluator(student, metric=self.metric)
            trainset_scores = [r[-1] for r in valset_evaluation.results[len(valset):]]
            valset_scores = [r[-1] for r in valset_evaluation.results[:len(valset)]]
            trainset_agg = sum(trainset_scores) / len(trainset_scores)
            valset_agg = sum(valset_scores) / len(valset_scores)
            if step_idx == -1:
                logger.info(f"Student program training set score before training loop: {trainset_agg}")
                logger.info(f"Student program validation set score before training loop: {valset_agg}")
            else:
                logger.info(f"Student program training set score after training step {step_idx + 1}/{self.num_train_steps}: {trainset_agg}")
                logger.info(f"Student program validation set score after training step {step_idx + 1}/{self.num_train_steps}: {valset_agg}")
        else:
            if step_idx == -1:
                logger.info("Using user provided validation set and not reporting train scores.")
            valset_evaluator = Evaluate(
                devset=valset,
                num_threads=self.num_threads,
                display_progress=True,
                provide_traceback=False,  # TODO(check with team)
                max_errors=len(valset)*10,  # TODO(check with team)
                failure_score=self.failure_score
            )
            if step_idx == -1:
                logger.info("Evaluating the student program on the validation set before training loop...")
            else:
                logger.info(f"Evaluating the student program on the validation set after training step {step_idx + 1}/{self.num_train_steps}")
            valset_evaluation = valset_evaluator(student, metric=self.metric)
            if step_idx == -1:
                logger.info(f"Student program validation set score before training loop: {valset_evaluation.score}")
            else:
                logger.info(f"Student program validation set score after training step {step_idx + 1}/{self.num_train_steps}: {valset_evaluation.score}")
    else:
        # No validation set provided by user
        if self.report_train_scores:
            assert self.use_train_as_val, "If report_train_scores is True, use_train_as_val must be True when valset is not provided explicitly."
            assert isinstance(self.num_steps_for_val, int) and self.num_steps_for_val > 0, "num_steps_for_val must be a positive integer."
            if step_idx == -1:
                logger.info("Using trainset as validation set.")
            valset_evaluator = Evaluate(
                devset=trainset,
                num_threads=self.num_threads,
                display_progress=True,
                provide_traceback=False,  # TODO(check with team)
                max_errors=len(trainset)*10,  # TODO(check with team)
                failure_score=self.failure_score
            )
            if step_idx == -1:
                logger.info("Evaluating the student program on the validation set before training loop...")
            else:
                logger.info(f"Evaluating the student program on the validation set after training step {step_idx + 1}/{self.num_train_steps}")
            valset_evaluation = valset_evaluator(student, metric=self.metric)
            if step_idx == -1:
                logger.info(f"Student program training set score before training loop: {valset_evaluation.score}")
            else:
                logger.info(f"Student program training set score after training step {step_idx + 1}/{self.num_train_steps}: {valset_evaluation.score}")
        else:
            # No valset provided, and not using train as val
            assert not self.use_train_as_val, "If report_train_scores is False, use_train_as_val must be False."
            if step_idx == -1:
                logger.info("Not using any validation set and not reporting train scores.")

def update_shuffled_trainset(self, original_trainset):
    self.shuffled_trainset_ids = list(range(len(original_trainset)))
    self.rng.shuffle(self.shuffled_trainset_ids)
    for id in self.shuffled_trainset_ids:
        self.id_freqs[id] += 1

    num_to_pad = self.num_dspy_examples_per_grpo_step - (len(original_trainset) % self.num_dspy_examples_per_grpo_step)
    if num_to_pad > 0:
        # Select ids based on least frequent ids
        for _ in range(num_to_pad):
            selected_id = self.id_freqs.most_common()[::-1][0][0]
            self.shuffled_trainset_ids.append(selected_id)
            self.id_freqs[selected_id] += 1

class Settings:
    """
    A singleton class for DSPy configuration settings.
    Thread-safe global configuration.
    - 'configure' can be called by only one 'owner' thread (the first thread that calls it).
    - Other threads see the configured global values from 'main_thread_config'.
    - 'context' sets thread-local overrides. These overrides propagate to threads spawned
      inside that context block, when (and only when!) using a ParallelExecutor that copies overrides.

      1. Only one unique thread (which can be any thread!) can call dspy.configure.
      2. It affects a global state, visible to all. As a result, user threads work, but they shouldn't be
         mixed with concurrent changes to dspy.configure from the "main" thread.
         (TODO: In the future, add warnings: if there are near-in-time user-thread reads followed by .configure calls.)
      3. Any thread can use dspy.context. It propagates to child threads created with DSPy primitives: Parallel, asyncify, etc.
    """

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    @property
    def lock(self):
        return global_lock

    def __getattr__(self, name):
        overrides = thread_local_overrides.get()
        if name in overrides:
            return overrides[name]
        elif name in main_thread_config:
            return main_thread_config[name]
        else:
            raise AttributeError(f"'Settings' object has no attribute '{name}'")

    def __setattr__(self, name, value):
        if name in ("_instance",):
            super().__setattr__(name, value)
        else:
            self.configure(**{name: value})

    def __getitem__(self, key):
        return self.__getattr__(key)

    def __setitem__(self, key, value):
        self.__setattr__(key, value)

    def __contains__(self, key):
        overrides = thread_local_overrides.get()
        return key in overrides or key in main_thread_config

    def get(self, key, default=None):
        try:
            return self[key]
        except AttributeError:
            return default

    def copy(self):
        overrides = thread_local_overrides.get()
        return dotdict({**main_thread_config, **overrides})

    @property
    def config(self):
        return self.copy()

    def _ensure_configure_allowed(self):
        global main_thread_config, config_owner_thread_id, config_owner_async_task
        current_thread_id = threading.get_ident()

        if config_owner_thread_id is None:
            # First `configure` call assigns the owner thread id.
            config_owner_thread_id = current_thread_id

        if config_owner_thread_id != current_thread_id:
            # Disallow a second `configure` calls from other threads.
            raise RuntimeError("dspy.settings can only be changed by the thread that initially configured it.")

        # Async task doesn't allow a second `configure` call, must use dspy.context(...) instead.
        is_async_task = False
        try:
            if asyncio.current_task() is not None:
                is_async_task = True
        except RuntimeError:
            # This exception (e.g., "no current task") means we are not in an async loop/task,
            # or asyncio module itself is not fully functional in this specific sub-thread context.
            is_async_task = False

        if not is_async_task:
            return

        if config_owner_async_task is None:
            # First `configure` call assigns the owner async task.
            config_owner_async_task = asyncio.current_task()
            return

        # We are in an async task. Now check for IPython and allow calling `configure` from IPython.
        in_ipython = False
        try:
            from IPython import get_ipython

            # get_ipython is a global injected by IPython environments.
            # We check its existence and type to be more robust.
            in_ipython = get_ipython() is not None
        except Exception:
            # If `IPython` is not installed or `get_ipython` failed, we are not in an IPython environment.
            in_ipython = False

        if not in_ipython and config_owner_async_task != asyncio.current_task():
            raise RuntimeError(
                "dspy.settings.configure(...) can only be called from the same async task that called it first. Please "
                "use `dspy.context(...)` in other async tasks instead."
            )

    def configure(self, **kwargs):
        # If no exception is raised, the `configure` call is allowed.
        self._ensure_configure_allowed()

        # Update global config
        for k, v in kwargs.items():
            main_thread_config[k] = v

    @contextmanager
    def context(self, **kwargs):
        """
        Context manager for temporary configuration changes at the thread level.
        Does not affect global configuration. Changes only apply to the current thread.
        If threads are spawned inside this block using ParallelExecutor, they will inherit these overrides.
        """

        original_overrides = thread_local_overrides.get().copy()
        new_overrides = dotdict({**main_thread_config, **original_overrides, **kwargs})
        token = thread_local_overrides.set(new_overrides)

        try:
            yield
        finally:
            thread_local_overrides.reset(token)

    def __repr__(self):
        overrides = thread_local_overrides.get()
        combined_config = {**main_thread_config, **overrides}
        return repr(combined_config)

def _get_test_program_signature_and_module_definition(program_description: str) -> str:
    """
    Generate the signature and model definition for a test DSPy program.

    Args:
        program_description: A description of the generated program.
    """
    use_cot = random.choice([True, False])
    if use_cot:
        program_var_definition = "program = dspy.ChainOfThought(program_signature)"
    else:
        program_var_definition = "program = dspy.Predict(program_signature)"

    return '''
import dspy

class BaseSignature(dspy.Signature):
    """
    {program_description}
    """

program_signature = BaseSignature
for input_field_name, input_field in ProgramInputs.model_fields.items():
    program_signature = program_signature.append(
        name=input_field_name,
        field=dspy.InputField(description=input_field.description),
        type_=input_field.annotation,
    )
for output_field_name, output_field in ProgramOutputs.model_fields.items():
    program_signature = program_signature.append(
        name=output_field_name,
        field=dspy.OutputField(description=input_field.description),
        type_=output_field.annotation,
    )

{program_var_definition}
'''.format(program_description=program_description, program_var_definition=program_var_definition)

class ArborTrainingJob(TrainingJob):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.provider_file_id = None
        self.provider_job_id = None

    def cancel(self):
        if ArborProvider.does_job_exist(self.provider_job_id):
            status = self.status()
            if ArborProvider.is_terminal_training_status(status):
                err_msg = "Jobs that are complete cannot be canceled."
                err_msg += f" Job with ID {self.provider_job_id} is done."
                raise Exception(err_msg)
            openai.fine_tuning.jobs.cancel(self.provider_job_id)
            self.provider_job_id = None

        if self.provider_file_id is not None:
            if ArborProvider.does_file_exist(self.provider_file_id):
                openai.files.delete(self.provider_file_id)
            self.provider_file_id = None

        super().cancel()

    def status(self) -> TrainingStatus:
        status = ArborProvider.get_training_status(self.provider_job_id)
        return status

class Column(Condition):
    arg_types = {"this": True, "table": False, "db": False, "catalog": False, "join_mark": False}

    @property
    def table(self) -> str:
        return self.text("table")

    @property
    def db(self) -> str:
        return self.text("db")

    @property
    def catalog(self) -> str:
        return self.text("catalog")

    @property
    def output_name(self) -> str:
        return self.name

    @property
    def parts(self) -> t.List[Identifier]:
        """Return the parts of a column in order catalog, db, table, name."""
        return [
            t.cast(Identifier, self.args[part])
            for part in ("catalog", "db", "table", "this")
            if self.args.get(part)
        ]

    def to_dot(self, include_dots: bool = True) -> Dot | Identifier:
        """Converts the column into a dot expression."""
        parts = self.parts
        parent = self.parent

        if include_dots:
            while isinstance(parent, Dot):
                parts.append(parent.expression)
                parent = parent.parent

        return Dot.build(deepcopy(parts)) if len(parts) > 1 else parts[0]

class Dot(Binary):
    @property
    def is_star(self) -> bool:
        return self.expression.is_star

    @property
    def name(self) -> str:
        return self.expression.name

    @property
    def output_name(self) -> str:
        return self.name

    @classmethod
    def build(self, expressions: t.Sequence[Expression]) -> Dot:
        """Build a Dot object with a sequence of expressions."""
        if len(expressions) < 2:
            raise ValueError("Dot requires >= 2 expressions.")

        return t.cast(Dot, reduce(lambda x, y: Dot(this=x, expression=y), expressions))

    @property
    def parts(self) -> t.List[Expression]:
        """Return the parts of a table / column in order catalog, db, table."""
        this, *parts = self.flatten()

        parts.reverse()

        for arg in COLUMN_PARTS:
            part = this.args.get(arg)

            if isinstance(part, Expression):
                parts.append(part)

        parts.reverse()
        return parts

def __new__(cls, clsname, bases, attrs):
    klass = super().__new__(cls, clsname, bases, attrs)
    enum = Dialects.__members__.get(clsname.upper())
    cls._classes[enum.value if enum is not None else clsname.lower()] = klass

    klass.TIME_TRIE = new_trie(klass.TIME_MAPPING)
    klass.FORMAT_TRIE = (
        new_trie(klass.FORMAT_MAPPING) if klass.FORMAT_MAPPING else klass.TIME_TRIE
    )
    klass.INVERSE_TIME_MAPPING = {v: k for k, v in klass.TIME_MAPPING.items()}
    klass.INVERSE_TIME_TRIE = new_trie(klass.INVERSE_TIME_MAPPING)
    klass.INVERSE_FORMAT_MAPPING = {v: k for k, v in klass.FORMAT_MAPPING.items()}
    klass.INVERSE_FORMAT_TRIE = new_trie(klass.INVERSE_FORMAT_MAPPING)

    klass.INVERSE_CREATABLE_KIND_MAPPING = {
        v: k for k, v in klass.CREATABLE_KIND_MAPPING.items()
    }

    base = seq_get(bases, 0)
    base_tokenizer = (getattr(base, "tokenizer_class", Tokenizer),)
    base_jsonpath_tokenizer = (getattr(base, "jsonpath_tokenizer_class", JSONPathTokenizer),)
    base_parser = (getattr(base, "parser_class", Parser),)
    base_generator = (getattr(base, "generator_class", Generator),)

    klass.tokenizer_class = klass.__dict__.get(
        "Tokenizer", type("Tokenizer", base_tokenizer, {})
    )
    klass.jsonpath_tokenizer_class = klass.__dict__.get(
        "JSONPathTokenizer", type("JSONPathTokenizer", base_jsonpath_tokenizer, {})
    )
    klass.parser_class = klass.__dict__.get("Parser", type("Parser", base_parser, {}))
    klass.generator_class = klass.__dict__.get(
        "Generator", type("Generator", base_generator, {})
    )

    klass.QUOTE_START, klass.QUOTE_END = list(klass.tokenizer_class._QUOTES.items())[0]
    klass.IDENTIFIER_START, klass.IDENTIFIER_END = list(
        klass.tokenizer_class._IDENTIFIERS.items()
    )[0]

    def get_start_end(token_type: TokenType) -> t.Tuple[t.Optional[str], t.Optional[str]]:
        return next(
            (
                (s, e)
                for s, (e, t) in klass.tokenizer_class._FORMAT_STRINGS.items()
                if t == token_type
            ),
            (None, None),
        )

    klass.BIT_START, klass.BIT_END = get_start_end(TokenType.BIT_STRING)
    klass.HEX_START, klass.HEX_END = get_start_end(TokenType.HEX_STRING)
    klass.BYTE_START, klass.BYTE_END = get_start_end(TokenType.BYTE_STRING)
    klass.UNICODE_START, klass.UNICODE_END = get_start_end(TokenType.UNICODE_STRING)

    if "\\" in klass.tokenizer_class.STRING_ESCAPES:
        klass.UNESCAPED_SEQUENCES = {
            **UNESCAPED_SEQUENCES,
            **klass.UNESCAPED_SEQUENCES,
        }

    klass.ESCAPED_SEQUENCES = {v: k for k, v in klass.UNESCAPED_SEQUENCES.items()}

    klass.SUPPORTS_COLUMN_JOIN_MARKS = "(+)" in klass.tokenizer_class.KEYWORDS

    if enum not in ("", "bigquery"):
        klass.generator_class.SELECT_KINDS = ()

    if enum not in ("", "athena", "presto", "trino", "duckdb"):
        klass.generator_class.TRY_SUPPORTED = False
        klass.generator_class.SUPPORTS_UESCAPE = False

    if enum not in ("", "databricks", "hive", "spark", "spark2"):
        modifier_transforms = klass.generator_class.AFTER_HAVING_MODIFIER_TRANSFORMS.copy()
        for modifier in ("cluster", "distribute", "sort"):
            modifier_transforms.pop(modifier, None)

        klass.generator_class.AFTER_HAVING_MODIFIER_TRANSFORMS = modifier_transforms

    if enum not in ("", "doris", "mysql"):
        klass.parser_class.ID_VAR_TOKENS = klass.parser_class.ID_VAR_TOKENS | {
            TokenType.STRAIGHT_JOIN,
        }
        klass.parser_class.TABLE_ALIAS_TOKENS = klass.parser_class.TABLE_ALIAS_TOKENS | {
            TokenType.STRAIGHT_JOIN,
        }

    if enum not in ("", "databricks", "oracle", "redshift", "snowflake", "spark"):
        klass.generator_class.SUPPORTS_DECODE_CASE = False

    if not klass.SUPPORTS_SEMI_ANTI_JOIN:
        klass.parser_class.TABLE_ALIAS_TOKENS = klass.parser_class.TABLE_ALIAS_TOKENS | {
            TokenType.ANTI,
            TokenType.SEMI,
        }

    return klass

def lowerhex_sql(self, expression: exp.LowerHex) -> str:
    text = self.func(self.HEX_FUNC, self.sql(expression, "this"))
    if not self.dialect.HEX_LOWERCASE:
        text = self.func("LOWER", text)
    return text

def ordered_sql(self, expression: exp.Ordered) -> str:
    desc = expression.args.get("desc")
    asc = not desc

    nulls_first = expression.args.get("nulls_first")
    nulls_last = not nulls_first
    nulls_are_large = self.dialect.NULL_ORDERING == "nulls_are_large"
    nulls_are_small = self.dialect.NULL_ORDERING == "nulls_are_small"
    nulls_are_last = self.dialect.NULL_ORDERING == "nulls_are_last"

    this = self.sql(expression, "this")

    sort_order = " DESC" if desc else (" ASC" if desc is False else "")
    nulls_sort_change = ""
    if nulls_first and (
        (asc and nulls_are_large) or (desc and nulls_are_small) or nulls_are_last
    ):
        nulls_sort_change = " NULLS FIRST"
    elif (
        nulls_last
        and ((asc and nulls_are_small) or (desc and nulls_are_large))
        and not nulls_are_last
    ):
        nulls_sort_change = " NULLS LAST"

    # If the NULLS FIRST/LAST clause is unsupported, we add another sort key to simulate it
    if nulls_sort_change and not self.NULL_ORDERING_SUPPORTED:
        window = expression.find_ancestor(exp.Window, exp.Select)
        if isinstance(window, exp.Window) and window.args.get("spec"):
            self.unsupported(
                f"'{nulls_sort_change.strip()}' translation not supported in window functions"
            )
            nulls_sort_change = ""
        elif self.NULL_ORDERING_SUPPORTED is False and (
            (asc and nulls_sort_change == " NULLS LAST")
            or (desc and nulls_sort_change == " NULLS FIRST")
        ):
            # BigQuery does not allow these ordering/nulls combinations when used under
            # an aggregation func or under a window containing one
            ancestor = expression.find_ancestor(exp.AggFunc, exp.Window, exp.Select)

            if isinstance(ancestor, exp.Window):
                ancestor = ancestor.this
            if isinstance(ancestor, exp.AggFunc):
                self.unsupported(
                    f"'{nulls_sort_change.strip()}' translation not supported for aggregate functions with {sort_order} sort order"
                )
                nulls_sort_change = ""
        elif self.NULL_ORDERING_SUPPORTED is None:
            if expression.this.is_int:
                self.unsupported(
                    f"'{nulls_sort_change.strip()}' translation not supported with positional ordering"
                )
            elif not isinstance(expression.this, exp.Rand):
                null_sort_order = " DESC" if nulls_sort_change == " NULLS FIRST" else ""
                this = f"CASE WHEN {this} IS NULL THEN 1 ELSE 0 END{null_sort_order}, {this}"
            nulls_sort_change = ""

    with_fill = self.sql(expression, "with_fill")
    with_fill = f" {with_fill}" if with_fill else ""

    return f"{this}{sort_order}{nulls_sort_change}{with_fill}"

def bracket_offset_expressions(
    self, expression: exp.Bracket, index_offset: t.Optional[int] = None
) -> t.List[exp.Expression]:
    return apply_index_offset(
        expression.this,
        expression.expressions,
        (index_offset or self.dialect.INDEX_OFFSET) - expression.args.get("offset", 0),
        dialect=self.dialect,
    )

def json_path_part(self, expression: int | str | exp.JSONPathPart) -> str:
    if isinstance(expression, exp.JSONPathPart):
        transform = self.TRANSFORMS.get(expression.__class__)
        if not callable(transform):
            self.unsupported(f"Unsupported JSONPathPart type {expression.__class__.__name__}")
            return ""

        return transform(self, expression)

    if isinstance(expression, int):
        return str(expression)

    if self._quote_json_path_key_using_brackets and self.JSON_PATH_SINGLE_QUOTE_ESCAPE:
        escaped = expression.replace("'", "\\'")
        escaped = f"\\'{expression}\\'"
    else:
        escaped = expression.replace('"', '\\"')
        escaped = f'"{escaped}"'

    return escaped

def connector_sql(
    self,
    expression: exp.Connector,
    op: str,
    stack: t.Optional[t.List[str | exp.Expression]] = None,
) -> str:
    if stack is not None:
        if expression.expressions:
            stack.append(self.expressions(expression, sep=f" {op} "))
        else:
            stack.append(expression.right)
            if expression.comments and self.comments:
                for comment in expression.comments:
                    if comment:
                        op += f" /*{self.sanitize_comment(comment)}*/"
            stack.extend((op, expression.left))
        return op

    stack = [expression]
    sqls: t.List[str] = []
    ops = set()

    while stack:
        node = stack.pop()
        if isinstance(node, exp.Connector):
            ops.add(getattr(self, f"{node.key}_sql")(node, stack))
        else:
            sql = self.sql(node)
            if sqls and sqls[-1] in ops:
                sqls[-1] += f" {sql}"
            else:
                sqls.append(sql)

    sep = "\n" if self.pretty and self.too_wide(sqls) else " "
    return sep.join(sqls)

def function_fallback_sql(self, expression: exp.Func) -> str:
    args = []

    for key in expression.arg_types:
        arg_value = expression.args.get(key)

        if isinstance(arg_value, list):
            for value in arg_value:
                args.append(value)
        elif arg_value is not None:
            args.append(arg_value)

    if self.dialect.PRESERVE_ORIGINAL_NAMES:
        name = (expression._meta and expression.meta.get("name")) or expression.sql_name()
    else:
        name = expression.sql_name()

    return self.func(name, *args)

def anyvalue_sql(self, expression: exp.AnyValue) -> str:
    this = self.sql(expression, "this")
    having = self.sql(expression, "having")

    if having:
        this = f"{this} HAVING {'MAX' if expression.args.get('max') else 'MIN'} {having}"

    return self.func("ANY_VALUE", this)

def struct_sql(self, expression: exp.Struct) -> str:
    expression.set(
        "expressions",
        [
            exp.alias_(e.expression, e.name if e.this.is_string else e.this)
            if isinstance(e, exp.PropertyEQ)
            else e
            for e in expression.expressions
        ],
    )

    return self.function_fallback_sql(expression)

def arrayconcat_sql(self, expression: exp.ArrayConcat, name: str = "ARRAY_CONCAT") -> str:
    exprs = expression.expressions
    if not self.ARRAY_CONCAT_IS_VAR_LEN:
        rhs = reduce(lambda x, y: exp.ArrayConcat(this=x, expressions=[y]), exprs)
    else:
        rhs = self.expressions(expression)

    return self.func(name, expression.this, rhs or None)

def partitionbyrangepropertydynamic_sql(
    self, expression: exp.PartitionByRangePropertyDynamic
) -> str:
    start = self.sql(expression, "start")
    end = self.sql(expression, "end")

    every = expression.args["every"]
    if isinstance(every, exp.Interval) and every.this.is_string:
        every.this.replace(exp.Literal.number(every.name))

    return f"START {self.wrap(start)} END {self.wrap(end)} EVERY {self.wrap(self.sql(every))}"

def parameterizedagg_sql(self, expression: exp.ParameterizedAgg) -> str:
    params = self.expressions(expression, key="params", flat=True)
    return self.func(expression.name, *expression.expressions) + f"({params})"

def eliminate_window_clause(expression: exp.Expression) -> exp.Expression:
    """Eliminates the `WINDOW` query clause by inling each named window."""
    if isinstance(expression, exp.Select) and expression.args.get("windows"):
        from sqlglot.optimizer.scope import find_all_in_scope

        windows = expression.args["windows"]
        expression.set("windows", None)

        window_expression: t.Dict[str, exp.Expression] = {}

        def _inline_inherited_window(window: exp.Expression) -> None:
            inherited_window = window_expression.get(window.alias.lower())
            if not inherited_window:
                return

            window.set("alias", None)
            for key in ("partition_by", "order", "spec"):
                arg = inherited_window.args.get(key)
                if arg:
                    window.set(key, arg.copy())

        for window in windows:
            _inline_inherited_window(window)
            window_expression[window.name.lower()] = window

        for window in find_all_in_scope(expression, exp.Window):
            _inline_inherited_window(window)

    return expression

def _traverse_udtfs(scope):
    if isinstance(scope.expression, exp.Unnest):
        expressions = scope.expression.expressions
    elif isinstance(scope.expression, exp.Lateral):
        expressions = [scope.expression.this]
    else:
        expressions = []

    sources = {}
    for expression in expressions:
        if _is_derived_table(expression):
            top = None
            for child_scope in _traverse_scope(
                scope.branch(
                    expression,
                    scope_type=ScopeType.SUBQUERY,
                    outer_columns=expression.alias_column_names,
                )
            ):
                yield child_scope
                top = child_scope
                sources[_get_source_alias(expression)] = child_scope

            scope.subquery_scopes.append(top)

    scope.sources.update(sources)

def _expand_stars(
    scope: Scope,
    resolver: Resolver,
    using_column_tables: t.Dict[str, t.Any],
    pseudocolumns: t.Set[str],
    annotator: TypeAnnotator,
) -> None:
    """Expand stars to lists of column selections"""

    new_selections: t.List[exp.Expression] = []
    except_columns: t.Dict[int, t.Set[str]] = {}
    replace_columns: t.Dict[int, t.Dict[str, exp.Alias]] = {}
    rename_columns: t.Dict[int, t.Dict[str, str]] = {}

    coalesced_columns = set()
    dialect = resolver.schema.dialect

    pivot_output_columns = None
    pivot_exclude_columns: t.Set[str] = set()

    pivot = t.cast(t.Optional[exp.Pivot], seq_get(scope.pivots, 0))
    if isinstance(pivot, exp.Pivot) and not pivot.alias_column_names:
        if pivot.unpivot:
            pivot_output_columns = [c.output_name for c in _unpivot_columns(pivot)]

            for field in pivot.fields:
                if isinstance(field, exp.In):
                    pivot_exclude_columns.update(
                        c.output_name for e in field.expressions for c in e.find_all(exp.Column)
                    )

        else:
            pivot_exclude_columns = set(c.output_name for c in pivot.find_all(exp.Column))

            pivot_output_columns = [c.output_name for c in pivot.args.get("columns", [])]
            if not pivot_output_columns:
                pivot_output_columns = [c.alias_or_name for c in pivot.expressions]

    is_bigquery = dialect == "bigquery"
    is_risingwave = dialect == "risingwave"

    if (is_bigquery or is_risingwave) and any(isinstance(col, exp.Dot) for col in scope.stars):
        # Found struct expansion, annotate scope ahead of time
        annotator.annotate_scope(scope)

    for expression in scope.expression.selects:
        tables = []
        if isinstance(expression, exp.Star):
            tables.extend(scope.selected_sources)
            _add_except_columns(expression, tables, except_columns)
            _add_replace_columns(expression, tables, replace_columns)
            _add_rename_columns(expression, tables, rename_columns)
        elif expression.is_star:
            if not isinstance(expression, exp.Dot):
                tables.append(expression.table)
                _add_except_columns(expression.this, tables, except_columns)
                _add_replace_columns(expression.this, tables, replace_columns)
                _add_rename_columns(expression.this, tables, rename_columns)
            elif is_bigquery:
                struct_fields = _expand_struct_stars_bigquery(expression)
                if struct_fields:
                    new_selections.extend(struct_fields)
                    continue
            elif is_risingwave:
                struct_fields = _expand_struct_stars_risingwave(expression)
                if struct_fields:
                    new_selections.extend(struct_fields)
                    continue

        if not tables:
            new_selections.append(expression)
            continue

        for table in tables:
            if table not in scope.sources:
                raise OptimizeError(f"Unknown table: {table}")

            columns = resolver.get_source_columns(table, only_visible=True)
            columns = columns or scope.outer_columns

            if pseudocolumns:
                columns = [name for name in columns if name.upper() not in pseudocolumns]

            if not columns or "*" in columns:
                return

            table_id = id(table)
            columns_to_exclude = except_columns.get(table_id) or set()
            renamed_columns = rename_columns.get(table_id, {})
            replaced_columns = replace_columns.get(table_id, {})

            if pivot:
                if pivot_output_columns and pivot_exclude_columns:
                    pivot_columns = [c for c in columns if c not in pivot_exclude_columns]
                    pivot_columns.extend(pivot_output_columns)
                else:
                    pivot_columns = pivot.alias_column_names

                if pivot_columns:
                    new_selections.extend(
                        alias(exp.column(name, table=pivot.alias), name, copy=False)
                        for name in pivot_columns
                        if name not in columns_to_exclude
                    )
                    continue

            for name in columns:
                if name in columns_to_exclude or name in coalesced_columns:
                    continue
                if name in using_column_tables and table in using_column_tables[name]:
                    coalesced_columns.add(name)
                    tables = using_column_tables[name]
                    coalesce_args = [exp.column(name, table=table) for table in tables]

                    new_selections.append(
                        alias(exp.func("coalesce", *coalesce_args), alias=name, copy=False)
                    )
                else:
                    alias_ = renamed_columns.get(name, name)
                    selection_expr = replaced_columns.get(name) or exp.column(name, table=table)
                    new_selections.append(
                        alias(selection_expr, alias_, copy=False)
                        if alias_ != name
                        else selection_expr
                    )

    # Ensures we don't overwrite the initial selections with an empty list
    if new_selections and isinstance(scope.expression, exp.Select):
        scope.expression.set("expressions", new_selections)

class Node:
    name: str
    expression: exp.Expression
    source: exp.Expression
    downstream: t.List[Node] = field(default_factory=list)
    source_name: str = ""
    reference_node_name: str = ""

    def walk(self) -> t.Iterator[Node]:
        yield self

        for d in self.downstream:
            yield from d.walk()

    def to_html(self, dialect: DialectType = None, **opts) -> GraphHTML:
        nodes = {}
        edges = []

        for node in self.walk():
            if isinstance(node.expression, exp.Table):
                label = f"FROM {node.expression.this}"
                title = f"<pre>SELECT {node.name} FROM {node.expression.this}</pre>"
                group = 1
            else:
                label = node.expression.sql(pretty=True, dialect=dialect)
                source = node.source.transform(
                    lambda n: (
                        exp.Tag(this=n, prefix="<b>", postfix="</b>") if n is node.expression else n
                    ),
                    copy=False,
                ).sql(pretty=True, dialect=dialect)
                title = f"<pre>{source}</pre>"
                group = 0

            node_id = id(node)

            nodes[node_id] = {
                "id": node_id,
                "label": label,
                "title": title,
                "group": group,
            }

            for d in node.downstream:
                edges.append({"from": node_id, "to": id(d)})
        return GraphHTML(nodes, edges, **opts)

class TestTextEmbedding(EmbeddingModelBase):
    """A mock text embedding model for testing."""

    supported_modalities: list[str] = ["text"]
    """This class only supports text input."""

    def __init__(self) -> None:
        """The constructor for the mock text embedding model."""
        super().__init__(model_name="mock-model", dimensions=3)

    async def __call__(
        self,
        text: list[TextBlock | str],
        **kwargs: Any,
    ) -> EmbeddingResponse:
        """Return a fixed embedding for testing."""
        embeddings = []
        for t in text:
            if isinstance(t, dict):
                t = t.get("text")
            if t == "This is an apple":
                embeddings.append([0.1, 0.2, 0.3])
            elif t == "This is a banana":
                embeddings.append([0.9, 0.1, 0.4])
            elif t == "apple":
                embeddings.append([0.15, 0.25, 0.35])

        return EmbeddingResponse(
            embeddings=embeddings,
        )

class UrlMappingMatchInfo(BaseDict, AbstractMatchInfo):

    __slots__ = ("_route", "_apps", "_current_app", "_frozen")

    def __init__(self, match_dict: Dict[str, str], route: AbstractRoute) -> None:
        super().__init__(match_dict)
        self._route = route
        self._apps: List[Application] = []
        self._current_app: Optional[Application] = None
        self._frozen = False

    @property
    def handler(self) -> Handler:
        return self._route.handler

    @property
    def route(self) -> AbstractRoute:
        return self._route

    @property
    def expect_handler(self) -> _ExpectHandler:
        return self._route.handle_expect_header

    @property
    def http_exception(self) -> Optional[HTTPException]:
        return None

    def get_info(self) -> _InfoDict:  # type: ignore[override]
        return self._route.get_info()

    @property
    def apps(self) -> Tuple["Application", ...]:
        return tuple(self._apps)

    def add_app(self, app: "Application") -> None:
        if self._frozen:
            raise RuntimeError("Cannot change apps stack after .freeze() call")
        if self._current_app is None:
            self._current_app = app
        self._apps.insert(0, app)

    @property
    def current_app(self) -> "Application":
        app = self._current_app
        assert app is not None
        return app

    @current_app.setter
    def current_app(self, app: "Application") -> None:
        if DEBUG:  # pragma: no cover
            if app not in self._apps:
                raise RuntimeError(
                    "Expected one of the following apps {!r}, got {!r}".format(
                        self._apps, app
                    )
                )
        self._current_app = app

    def freeze(self) -> None:
        self._frozen = True

    def __repr__(self) -> str:
        return f"<MatchInfo {super().__repr__()}: {self._route}>"

class FormData:
    """Helper class for form body generation.

    Supports multipart/form-data and application/x-www-form-urlencoded.
    """

    def __init__(
        self,
        fields: Iterable[Any] = (),
        quote_fields: bool = True,
        charset: Optional[str] = None,
        boundary: Optional[str] = None,
        *,
        default_to_multipart: bool = False,
    ) -> None:
        self._boundary = boundary
        self._writer = multipart.MultipartWriter("form-data", boundary=self._boundary)
        self._fields: List[Any] = []
        self._is_multipart = default_to_multipart
        self._quote_fields = quote_fields
        self._charset = charset

        if isinstance(fields, dict):
            fields = list(fields.items())
        elif not isinstance(fields, (list, tuple)):
            fields = (fields,)
        self.add_fields(*fields)

    @property
    def is_multipart(self) -> bool:
        return self._is_multipart

    def add_field(
        self,
        name: str,
        value: Any,
        *,
        content_type: Optional[str] = None,
        filename: Optional[str] = None,
    ) -> None:
        if isinstance(value, (io.IOBase, bytes, bytearray, memoryview)):
            self._is_multipart = True

        type_options: MultiDict[str] = MultiDict({"name": name})
        if filename is not None and not isinstance(filename, str):
            raise TypeError("filename must be an instance of str. Got: %s" % filename)
        if filename is None and isinstance(value, io.IOBase):
            filename = guess_filename(value, name)
        if filename is not None:
            type_options["filename"] = filename
            self._is_multipart = True

        headers = {}
        if content_type is not None:
            if not isinstance(content_type, str):
                raise TypeError(
                    "content_type must be an instance of str. Got: %s" % content_type
                )
            headers[hdrs.CONTENT_TYPE] = content_type
            self._is_multipart = True

        self._fields.append((type_options, headers, value))

    def add_fields(self, *fields: Any) -> None:
        to_add = list(fields)

        while to_add:
            rec = to_add.pop(0)

            if isinstance(rec, io.IOBase):
                k = guess_filename(rec, "unknown")
                self.add_field(k, rec)  # type: ignore[arg-type]

            elif isinstance(rec, (MultiDictProxy, MultiDict)):
                to_add.extend(rec.items())

            elif isinstance(rec, (list, tuple)) and len(rec) == 2:
                k, fp = rec
                self.add_field(k, fp)

            else:
                raise TypeError(
                    "Only io.IOBase, multidict and (name, file) "
                    "pairs allowed, use .add_field() for passing "
                    "more complex parameters, got {!r}".format(rec)
                )

    def _gen_form_urlencoded(self) -> payload.BytesPayload:
        # form data (x-www-form-urlencoded)
        data = []
        for type_options, _, value in self._fields:
            if not isinstance(value, str):
                raise TypeError(f"expected str, got {value!r}")
            data.append((type_options["name"], value))

        charset = self._charset if self._charset is not None else "utf-8"

        if charset == "utf-8":
            content_type = "application/x-www-form-urlencoded"
        else:
            content_type = "application/x-www-form-urlencoded; charset=%s" % charset

        return payload.BytesPayload(
            urlencode(data, doseq=True, encoding=charset).encode(),
            content_type=content_type,
        )

    def _gen_form_data(self) -> multipart.MultipartWriter:
        """Encode a list of fields using the multipart/form-data MIME format"""
        for dispparams, headers, value in self._fields:
            try:
                if hdrs.CONTENT_TYPE in headers:
                    part = payload.get_payload(
                        value,
                        content_type=headers[hdrs.CONTENT_TYPE],
                        headers=headers,
                        encoding=self._charset,
                    )
                else:
                    part = payload.get_payload(
                        value, headers=headers, encoding=self._charset
                    )
            except Exception as exc:
                raise TypeError(
                    "Can not serialize value type: %r\n "
                    "headers: %r\n value: %r" % (type(value), headers, value)
                ) from exc

            if dispparams:
                part.set_content_disposition(
                    "form-data", quote_fields=self._quote_fields, **dispparams
                )
                # FIXME cgi.FieldStorage doesn't likes body parts with
                # Content-Length which were sent via chunked transfer encoding
                assert part.headers is not None
                part.headers.popall(hdrs.CONTENT_LENGTH, None)

            self._writer.append_payload(part)

        self._fields.clear()
        return self._writer

    def __call__(self) -> Payload:
        if self._is_multipart:
            return self._gen_form_data()
        else:
            return self._gen_form_urlencoded()

