async def _descovery_metadata(
    self,
    server_url: str,
) -> Optional[MCPOAuthMetadata]:
    """Discover OAuth metadata by following RFC 9728 (protected resource metadata discovery)."""

    try:
        async with httpx.AsyncClient(timeout=10.0, follow_redirects=False) as client:
            response = await client.get(server_url)
            response.raise_for_status()
        verbose_logger.warning(
            "MCP OAuth discovery unexpectedly succeeded for %s; server did not challenge",
            server_url,
        )
        raise RuntimeError("OAuth discovery must not succeed without a challenge")
    except HTTPStatusError as exc:
        verbose_logger.debug(
            "MCP OAuth discovery for %s received status error: %s",
            server_url,
            exc,
        )

        header_value: Optional[str] = None
        if exc.response is not None:
            header_value = (
                exc.response.headers.get("WWW-Authenticate")
                or exc.response.headers.get("www-authenticate")
            )

        resource_metadata_url, scopes = self._parse_www_authenticate_header(
            header_value
        )

        authorization_servers: List[str] = []
        resource_scopes: Optional[List[str]] = None
        if resource_metadata_url:
            (
                authorization_servers,
                resource_scopes,
            ) = await self._fetch_oauth_metadata_from_resource(resource_metadata_url)
        else:
            (
                authorization_servers,
                resource_scopes,
            ) = await self._attempt_well_known_discovery(server_url)

        metadata = None
        if not authorization_servers:
            try:
                parsed_url = urlparse(server_url)
                if parsed_url.scheme and parsed_url.netloc:
                    authorization_servers = [
                        f"{parsed_url.scheme}://{parsed_url.netloc}"
                    ]
            except Exception:
                authorization_servers = []

        if authorization_servers:
            metadata = await self._fetch_authorization_server_metadata(
                authorization_servers
            )

        preferred_scopes = scopes or resource_scopes
        if metadata is None and preferred_scopes:
            metadata = MCPOAuthMetadata(scopes=preferred_scopes)
        elif metadata is not None and preferred_scopes:
            metadata.scopes = preferred_scopes

        return metadata
    except Exception as exc:  # pragma: no cover - network/transient issues
        verbose_logger.debug(
            "MCP OAuth discovery failed for %s: %s", server_url, exc
        )
        return None

def validate_environment(
    self,
    presidio_analyzer_api_base: Optional[str] = None,
    presidio_anonymizer_api_base: Optional[str] = None,
):
    self.presidio_analyzer_api_base: Optional[
        str
    ] = presidio_analyzer_api_base or get_secret(
        "PRESIDIO_ANALYZER_API_BASE", None
    )  # type: ignore
    self.presidio_anonymizer_api_base: Optional[
        str
    ] = presidio_anonymizer_api_base or litellm.get_secret(
        "PRESIDIO_ANONYMIZER_API_BASE", None
    )  # type: ignore

    if self.presidio_analyzer_api_base is None:
        raise Exception("Missing `PRESIDIO_ANALYZER_API_BASE` from environment")
    if not self.presidio_analyzer_api_base.endswith("/"):
        self.presidio_analyzer_api_base += "/"
    if not (
        self.presidio_analyzer_api_base.startswith("http://")
        or self.presidio_analyzer_api_base.startswith("https://")
    ):
        # add http:// if unset, assume communicating over private network - e.g. render
        self.presidio_analyzer_api_base = (
            "http://" + self.presidio_analyzer_api_base
        )

    if self.presidio_anonymizer_api_base is None:
        raise Exception("Missing `PRESIDIO_ANONYMIZER_API_BASE` from environment")
    if not self.presidio_anonymizer_api_base.endswith("/"):
        self.presidio_anonymizer_api_base += "/"
    if not (
        self.presidio_anonymizer_api_base.startswith("http://")
        or self.presidio_anonymizer_api_base.startswith("https://")
    ):
        # add http:// if unset, assume communicating over private network - e.g. render
        self.presidio_anonymizer_api_base = (
            "http://" + self.presidio_anonymizer_api_base
        )

def stream_chunk_builder_text_completion(
    chunks: list, messages: Optional[List] = None
) -> TextCompletionResponse:
    id = chunks[0]["id"]
    object = chunks[0]["object"]
    created = chunks[0]["created"]
    model = chunks[0]["model"]
    system_fingerprint = chunks[0].get("system_fingerprint", None)
    finish_reason = chunks[-1]["choices"][0]["finish_reason"]
    logprobs = chunks[-1]["choices"][0]["logprobs"]

    response = {
        "id": id,
        "object": object,
        "created": created,
        "model": model,
        "system_fingerprint": system_fingerprint,
        "choices": [
            {
                "text": None,
                "index": 0,
                "logprobs": logprobs,
                "finish_reason": finish_reason,
            }
        ],
        "usage": {
            "prompt_tokens": None,
            "completion_tokens": None,
            "total_tokens": None,
        },
    }
    content_list = []
    for chunk in chunks:
        choices = chunk["choices"]
        for choice in choices:
            if (
                choice is not None
                and hasattr(choice, "text")
                and choice.get("text") is not None
            ):
                _choice = choice.get("text")
                content_list.append(_choice)

    # Combine the "content" strings into a single string || combine the 'function' strings into a single string
    combined_content = "".join(content_list)

    # Update the "content" field within the response dictionary
    response["choices"][0]["text"] = combined_content

    if len(combined_content) > 0:
        pass
    else:
        pass
    # # Update usage information if needed
    try:
        response["usage"]["prompt_tokens"] = token_counter(
            model=model, messages=messages
        )
    except (
        Exception
    ):  # don't allow this failing to block a complete streaming response from being returned
        print_verbose("token_counter failed, assuming prompt tokens is 0")
        response["usage"]["prompt_tokens"] = 0
    response["usage"]["completion_tokens"] = token_counter(
        model=model,
        text=combined_content,
        count_response_tokens=True,  # count_response_tokens is a Flag to tell token counter this is a response, No need to add extra tokens we do for input messages
    )
    response["usage"]["total_tokens"] = (
        response["usage"]["prompt_tokens"] + response["usage"]["completion_tokens"]
    )
    return TextCompletionResponse(**response)

