class JsonAdapter(ABC):
    """NOT DOCUMENTED"""
    def register(self):
        _TaipyJsonAdapter().register(self)

    @abstractmethod
    def parse(self, o) -> t.Optional[t.Any]:
        ...  # pragma: no cover


class _DefaultJsonAdapter(JsonAdapter):
    def parse(self, o):
        if isinstance(o, Icon):
            return o._to_dict()
        if isinstance(o, _MapDict):
            return o._dict
        if isinstance(o, _TaipyBase):
            return o.get()
        if isinstance(o, (datetime, date, time)):
            return _date_to_string(o)
        if isinstance(o, Path):
            return str(o)
        if isinstance(o, (timedelta, pandas.Timedelta)):
            return str(o)
        if isinstance(o, numpy.generic):
            return getattr(o, "tolist", lambda: o)()
        if isinstance(o, _DoNotUpdate):
            return None


class _TaipyJsonAdapter(object, metaclass=_Singleton):
    def __init__(self) -> None:
        self._adapters: t.List[JsonAdapter] = []
        self.register(_DefaultJsonAdapter())

    def register(self, adapter: JsonAdapter):
        self._adapters.append(adapter)

    def parse(self, o):
        try:
            for adapter in reversed(self._adapters):
                if (output := adapter.parse(o)) is not None:
                    return output
            raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable (value: {o}).")
        except Exception as e:
            _warn("Exception while resolving JSON", e)
            return None


class _TaipyJsonEncoder(JSONEncoder):
    def default(self, o):
        return _TaipyJsonAdapter().parse(o)


class _TaipyJsonProvider(DefaultJSONProvider):
    default = staticmethod(_TaipyJsonAdapter().parse)
    sort_keys = False

def _patch_variable(
    self, var_name: str, change: t.Optional[dict] = None, remove: t.Optional[dict] = None, value: t.Any = None
) -> None:
    if value and (change or remove):
        # patch local variable
        _patch_value(value, change, remove)
        var_name = self._bind_var(var_name)
        deps = [dep for dep in self._get_variable_dependencies(var_name) if dep in self.__front_end_variables]
        if deps:
            # send patch to client
            self.__send_ws_patch(
                deps,
                change,
                remove,
            )

def _handle_disconnect(self):
    _Hooks()._handle_disconnect(self)
    if (sid := get_server_request_accessor(self).sid()) and (
        st_to := self._get_config("state_retention_period", 0)
    ) > 0:
        for cl_id, sids in self.__client_id_2_sid.items():
            if sid in sids:
                if len(sids) == 1:
                    Timer(st_to, self._remove_state, [cl_id]).start()
                else:
                    sids.remove(sid)
                return

def _upload_files(self):
    self.__set_client_id_in_context()
    on_upload_action = get_server_request_accessor(self).form().get("on_action", None)
    var_name = t.cast(str, get_server_request_accessor(self).form().get("var_name", None))
    if not var_name and not on_upload_action:
        _warn("upload files: No var name")
        return self._server.create_http_response("upload files: No var name", 400)
    context = get_server_request_accessor(self).form().get("context", None)
    upload_data = get_server_request_accessor(self).form().get("upload_data", None)
    multiple = (
        "multiple" in get_server_request_accessor(self).form()
        and get_server_request_accessor(self).form()["multiple"] == "True"
    )

    # File parsing and checks
    file = get_server_request_accessor(self).files().get("blob", None)
    if not file:
        _warn("upload files: No file part")
        return self._server.create_http_response("upload files: No file part", 400)
    # If the user does not select a file, the browser submits an
    # empty file without a filename.
    if file.filename == "":
        _warn("upload files: No selected file")
        return self._server.create_http_response("upload files: No selected file", 400)

    # Path parsing and checks
    path = get_server_request_accessor(self).form().get("path", "")
    suffix = ""
    complete = True
    part = 0

    if "total" in get_server_request_accessor(self).form():
        total = int(get_server_request_accessor(self).form()["total"])
        if total > 1 and "part" in get_server_request_accessor(self).form():
            part = int(get_server_request_accessor(self).form()["part"])
            suffix = f".part.{part}"
            complete = part == total - 1

    # Extract upload path (when single file is selected, path="" does not change the path)
    upload_root = os.path.abspath(self._get_config("upload_folder", tempfile.gettempdir()))
    upload_path = os.path.abspath(os.path.join(upload_root, os.path.dirname(path)))
    if upload_path.startswith(upload_root):
        upload_path = Path(upload_path).resolve()
        os.makedirs(upload_path, exist_ok=True)
        # Save file into upload_path directory
        file_path = _get_non_existent_file_path(upload_path, secure_filename(file.filename))
        self._server.save_uploaded_file(file, os.path.join(upload_path, (file_path.name + suffix)))
    else:
        _warn(f"upload files: Path {path} points outside of upload root.")
        return self._server.create_http_response("upload files: Path part points outside of upload root.", 400)

    if complete:
        if part > 0:
            try:
                with open(file_path, "wb") as grouped_file:
                    for nb in range(part + 1):
                        part_file_path = upload_path / f"{file_path.name}.part.{nb}"
                        with open(part_file_path, "rb") as part_file:
                            grouped_file.write(part_file.read())
                        # remove file_path after it is merged
                        part_file_path.unlink()
            except EnvironmentError as ee:  # pragma: no cover
                _warn(f"Cannot group file after chunk upload for {file.filename}", ee)
                return self._server.create_http_response(
                    f"Cannot group file after chunk upload for {file.filename}", 500
                )
        # Notify when file is uploaded
        newvalue = str(file_path)
        if multiple and var_name:
            value = _getscopeattr(self, var_name)  # type: ignore[arg-type]
            if not isinstance(value, t.List):
                value = [] if value is None else [value]
            value.append(newvalue)
            newvalue = value
        with self._set_locals_context(context):
            if on_upload_action:
                data = {}
                if upload_data:
                    try:
                        data = json.loads(upload_data)
                    except Exception:
                        pass
                data["path"] = file_path
                file_fn = self._get_user_function(on_upload_action)
                if not _is_function(file_fn):
                    file_fn = _getscopeattr(self, on_upload_action)  # type: ignore[arg-type]
                if _is_function(file_fn):
                    self._call_function_with_state(t.cast(t.Callable, file_fn), ["file_upload", {"args": [data]}])
            else:
                setattr(self._bindings(), var_name, newvalue)
    return self._server.create_http_response("", 200)

def _tbl_cols(
    self, rebuild: bool, rebuild_val: t.Optional[bool], attr_json: str, hash_json: str, **kwargs
) -> t.Union[str, _DoNotUpdate]:
    if not self.__is_building():
        try:
            rebuild = rebuild_val if rebuild_val is not None else rebuild
            if rebuild:
                attributes, hashes = self.__get_attributes(attr_json, hash_json, kwargs)
                data_hash = hashes.get("data", "")
                data = kwargs.get(data_hash)
                col_dict = _get_columns_dict(
                    attributes.get("columns", {}),
                    self._get_accessor().get_cols_description(data_hash, _TaipyData(data, data_hash)),
                    attributes.get("date_format"),
                    attributes.get("number_format"),
                )
                _enhance_columns(attributes, hashes, t.cast(dict, col_dict), "table(cols)")

                return json.dumps(col_dict, cls=_TaipyJsonEncoder)
        except Exception as e:  # pragma: no cover
            _warn("Exception while rebuilding table columns", e)
    return Gui.__DO_NOT_UPDATE_VALUE

class _Hooks(object, metaclass=_Singleton):
    def __init__(self):
        self.__hooks: t.List[_Hook] = []  # type: ignore[annotation-unchecked]

    def _register_hook(self, hook: _Hook):
        # Prevent duplicated hooks
        for h in self.__hooks:
            if type(hook) is type(h):
                _TaipyLogger._get_logger().info(f"Failed to register duplicated hook of type '{type(h)}'")
                return
        self.__hooks.append(hook)

    def __getattr__(self, name: str):
        def _resolve_hook(*args, **kwargs):
            for hook in self.__hooks:
                if name not in hook.method_names:
                    continue
                # call hook
                try:
                    func = getattr(hook, name)
                    if not callable(func):
                        raise Exception(f"'{name}' hook is not callable")
                    res = func(*args, **kwargs)
                except Exception as e:
                    _TaipyLogger._get_logger().error(f"Error while calling hook '{name}': {e}")
                    return
                # check if the hook returns True -> stop the chain
                if res is True:
                    return
                # only hooks that return true are allowed to return values to ensure consistent response
                if isinstance(res, (list, tuple)) and len(res) == 2 and res[0] is True:
                    return res[1]

        return _resolve_hook

def load_dataset_w_config(
    config_dataset: DictDefault, use_auth_token: bool, streaming=False
) -> Union[Dataset, DatasetDict]:
    """
    Load a dataset from a config

    Args:
        config_dataset: single dataset config
        use_auth_token: whether to use HF auth token
        streaming: whether to stream the dataset
    """
    # pylint: disable=invalid-name
    ds: Optional[Union[Dataset, DatasetDict]] = None  # pylint: disable=invalid-name
    ds_from_hub = False
    try:
        # this is just a basic check to see if the path is a
        # valid HF dataset that's loadable
        snapshot_download(
            repo_id=config_dataset.path,
            repo_type="dataset",
            token=use_auth_token,
            revision=config_dataset.revision,
            ignore_patterns=["*"],
        )
        ds_from_hub = True
    except (
        RepositoryNotFoundError,
        RevisionNotFoundError,
        FileNotFoundError,
        ConnectionError,
        HFValidationError,
        ValueError,
    ):
        pass

    ds_from_cloud = False
    storage_options: dict = {}
    remote_file_system = None
    if config_dataset.path.startswith("s3://"):
        try:
            import s3fs  # type: ignore
        except ImportError as exc:
            raise ImportError("s3:// paths require s3fs to be installed") from exc

        # Reads env, credentials from ~/.aws/credentials, or IAM metadata provider
        # https://s3fs.readthedocs.io/en/latest/index.html?highlight=storage_options#credentials
        storage_options = {"anon": False}
        remote_file_system = s3fs.S3FileSystem(**storage_options)
    elif config_dataset.path.startswith("gs://") or config_dataset.path.startswith(
        "gcs://"
    ):
        try:
            import gcsfs  # type: ignore
        except ImportError as exc:
            raise ImportError(
                "gs:// or gcs:// paths require gcsfs to be installed"
            ) from exc

        # gcsfs will use default credentials from the environment else anon
        # https://gcsfs.readthedocs.io/en/latest/#credentials
        storage_options = {"token": None}
        remote_file_system = gcsfs.GCSFileSystem(**storage_options)
    elif (
        config_dataset.path.startswith("adl://")
        or config_dataset.path.startswith("abfs://")
        or config_dataset.path.startswith("az://")
    ):
        try:
            import adlfs
        except ImportError as exc:
            raise ImportError(
                "adl:// or abfs:// paths require adlfs to be installed"
            ) from exc

        # # Ensure you have the following environment variables set:
        # # Gen 1
        # storage_options = {
        #     "tenant_id": AZURE_STORAGE_TENANT_ID,
        #     "client_id": AZURE_STORAGE_CLIENT_ID,
        #     "client_secret": AZURE_STORAGE_CLIENT_SECRET,
        # }
        # # Gen 2
        # storage_options = {
        #     "account_name": AZURE_STORAGE_ACCOUNT_NAME,
        #     "account_key": AZURE_STORAGE_ACCOUNT_KEY,
        # }

        # Reads env
        # https://github.com/fsspec/adlfs?tab=readme-ov-file#setting-credentials
        storage_options = {"anon": False}
        remote_file_system = adlfs.AzureBlobFileSystem(**storage_options)
    elif config_dataset.path.startswith("oci://"):
        try:
            import ocifs
        except ImportError as exc:
            raise ImportError("oci:// paths require ocifs to be installed") from exc

        # https://ocifs.readthedocs.io/en/latest/getting-connected.html#Using-Environment-Variables
        remote_file_system = ocifs.OCIFileSystem(**storage_options)

    try:
        if remote_file_system and remote_file_system.exists(config_dataset.path):
            ds_from_cloud = True
    except (FileNotFoundError, ConnectionError):
        pass

    # gather extra args from the config
    load_ds_kwargs = {}
    if config_dataset.split:
        load_ds_kwargs["split"] = config_dataset.split
    else:
        load_ds_kwargs["split"] = None

    # prefer local dataset, even if hub exists
    local_path = Path(config_dataset.path)
    if local_path.exists():
        if local_path.is_dir():
            if config_dataset.data_files:
                ds_type = get_ds_type(config_dataset)
                ds = load_dataset(  # pylint: disable=invalid-name
                    ds_type,
                    name=config_dataset.name,
                    data_files=config_dataset.data_files,
                    streaming=streaming,
                    **load_ds_kwargs,
                )
            else:
                try:
                    ds = load_from_disk(
                        config_dataset.path
                    )  # pylint: disable=invalid-name
                except FileNotFoundError:
                    ds = load_dataset(
                        config_dataset.path,
                        name=config_dataset.name,
                        streaming=False,
                        **load_ds_kwargs,
                    )
        elif local_path.is_file():
            ds_type = get_ds_type(config_dataset)

            ds = load_dataset(  # pylint: disable=invalid-name
                ds_type,
                name=config_dataset.name,
                data_files=config_dataset.path,
                streaming=False,
                **load_ds_kwargs,
            )
        else:
            raise ValueError(
                "unhandled dataset load: local path exists, but is neither a directory or a file"
            )
    elif ds_from_hub:
        ds = load_dataset(
            config_dataset.path,
            name=config_dataset.name,
            streaming=streaming,
            data_files=config_dataset.data_files,
            token=use_auth_token,
            revision=config_dataset.revision,
            trust_remote_code=config_dataset.trust_remote_code,
            **load_ds_kwargs,
        )
    elif ds_from_cloud and remote_file_system:
        if remote_file_system.isdir(config_dataset.path):
            ds = load_from_disk(
                config_dataset.path,
                storage_options=storage_options,
            )
        elif remote_file_system.isfile(config_dataset.path):
            ds_type = get_ds_type(config_dataset)
            ds = load_dataset(
                ds_type,
                name=config_dataset.name,
                data_files=config_dataset.path,
                streaming=streaming,
                storage_options=storage_options,
                trust_remote_code=config_dataset.trust_remote_code,
                **load_ds_kwargs,
            )
    elif config_dataset.path.startswith("https://"):
        ds_type = get_ds_type(config_dataset)
        ds = load_dataset(
            ds_type,
            name=config_dataset.name,
            data_files=config_dataset.path,
            streaming=streaming,
            storage_options=storage_options,
            trust_remote_code=config_dataset.trust_remote_code,
            **load_ds_kwargs,
        )
    elif config_dataset.data_files:
        fp: str | list[str] | None = None
        if isinstance(config_dataset.data_files, str):
            fp = hf_hub_download(
                repo_id=config_dataset.path,
                repo_type="dataset",
                filename=config_dataset.data_files,
                revision=config_dataset.revision,
            )
        elif isinstance(config_dataset.data_files, list):
            fp = []
            for file in config_dataset.data_files:
                fp.append(
                    hf_hub_download(
                        repo_id=config_dataset.path,
                        repo_type="dataset",
                        filename=file,
                        revision=config_dataset.revision,
                    )
                )
        else:
            raise ValueError("data_files must be either a string or list of strings")
        ds = load_dataset(
            "json",
            name=config_dataset.name,
            data_files=fp,
            streaming=streaming,
            **load_ds_kwargs,
        )
    if not ds:
        raise ValueError(
            "The dataset could not be loaded. This could be due to a misconfigured dataset path "
            f"({config_dataset.path}). Try double-check your path / name / data_files. "
            "This is not caused by the dataset type."
        )

    return ds

def datasets_w_name_generator(dataset_configs: list[DictDefault]):
    """
    Yields dataset configs handling multiple names or preprocess_shards

    Args:
        dataset_configs: list of dataset configs (equivalent to cfg.datasets)
    """
    for dataset in dataset_configs:
        if dataset.name and isinstance(dataset.name, list):
            # load_dataset doesn't properly handle multiple named configurations
            # at the same time for a given dataset
            for name in dataset.name:
                yield DictDefault({**dataset, "name": name})
        elif dataset.preprocess_shards and not dataset.shards:
            for shard in range(dataset.preprocess_shards):
                yield DictDefault(
                    {
                        **dataset,
                        "shards": dataset.preprocess_shards,
                        "shards_idx": shard,
                    }
                )
        else:
            yield dataset

